// Üretilen dosya: tool/ozgun/uret.py. Mühendislik ve Tasarım · Proje yönetimi, kalite ve güvenlik mühendisliği (orta).
const ozEngineering13Orta = <(String, String, List<String>, String)>[
  ('Bir ağda en erken başlama 5. gün, en geç başlama 9. gün olan etkinliğin toplam bolluğu kaç gündür?', '4', ['5', '9', '14'], 'Toplam bolluk = en geç başlama − en erken başlama = 9 − 5 = 4 gündür. Proje bitişini geciktirmeden etkinlik 4 gün kayabilir.'),
  ('Bir ağda birbirine paralel iki yolun da süresi tam 20 gün ve bu süre ağdaki en uzun süredir. Bu durum için hangisi doğrudur?', 'İki ayrı kritik yol vardır', ['Yalnız ilk yazılan yol kritiktir', 'Hiçbir yol kritik değildir', 'Ağ hatalı kurulmuştur'], 'En uzun süreye eşit birden çok yol aynı anda kritik olabilir. Bu durumda her iki yoldaki gecikme de projeyi geciktirir.'),
  ('Birden fazla etkinliğin birleştiği bir düğümde bir etkinliğin en erken başlama zamanı nasıl belirlenir?', 'Öncüllerinin en erken bitişlerinin en büyüğü alınır', ['Öncüllerinin en erken bitişlerinin ortalaması alınır', 'Öncüllerinin en erken bitişlerinin en küçüğü alınır', 'Öncüllerin süreleri toplanır'], 'Bir etkinlik tüm öncülleri bitmeden başlayamaz, bu yüzden en geç biten öncülün bitişi esas alınır. Bu nedenle en büyük değer seçilir.'),
  ('Bir etkinliğin en erken başlaması 7. gün ve süresi 5 gündür. Aynı etkinliğin en erken bitişi kaçıncı gündür?', '12', ['2', '7', '35'], 'En erken bitiş = en erken başlama + süre = 7 + 5 = 12\'dir.'),
  ('Bir etkinliğin en geç bitişi 20. gün, süresi 6 gündür. En geç başlaması kaçıncı gündür?', '14', ['26', '6', '120'], 'Geri geçişte en geç başlama = en geç bitiş − süre = 20 − 6 = 14\'tür.'),
  ('Bir etkinlik için iyimser süre 4, kötümser süre 16 gündür. PERT\'e göre standart sapma kaç gündür?', '2', ['3', '4', '12'], 'Standart sapma (b − a)/6 = (16 − 4)/6 = 2 gündür.'),
  ('Kötümser süre belirsizliği arttıkça (a ve m sabit) PERT beklenen süre ve standart sapma nasıl değişir?', 'İkisi de artar', ['İkisi de azalır', 'Beklenen süre artar, standart sapma azalır', 'İkisi de değişmez'], 'Hem (a + 4m + b)/6 hem de (b − a)/6 ifadesinde b pozitif katkı yapar. Bu yüzden b arttıkça ikisi de büyür.'),
  ('Proje süresini kısaltmak için kritik yoldaki etkinliklere ek kaynak koyup maliyeti artırmaya ne ad verilir?', 'Crashing', ['Fast tracking', 'Kapsam doğrulama', 'Kalite güvencesi'], 'Crashing, kritik yolda en az ek maliyetle süre kısaltmak için kaynak eklemektir. Fast tracking ise etkinlikleri örtüştürür.'),
  ('Normalde ardışık yapılan tasarım ve imalat adımlarını örtüştürerek paralel yürütmeye ne denir ve ana riski nedir?', 'Fast tracking; yeniden iş ve hata riski artar', ['Crashing; bütçe aşımı kesin olur', 'Kapsam doğrulama; kalite düşer', 'Kaynak dengeleme; süre uzar ve çalışan başına yük azalır'], 'Fast tracking süreyi kısaltır ama bağımlı işlerin örtüşmesi hata ve yeniden iş riskini yükseltir.'),
  ('EV = 80 ve gerçekleşen maliyet AC = 100 ise maliyet performans indeksi (CPI) kaçtır?', '0,8', ['1,25', '−20', '0,2'], 'CPI = EV/AC = 80/100 = 0,8\'dir. 1\'den küçük olması bütçenin aşıldığını gösterir.'),
  ('Bir projede EV = 60 ve AC = 75 ise maliyet sapması (CV) kaçtır?', '−15', ['+15', '−1,25', '+0,8'], 'CV = EV − AC = 60 − 75 = −15\'tir. Negatif değer bütçe aşımı demektir.'),
  ('Bir projenin CPI değeri 1,1, SPI değeri 0,85 çıkmıştır. Doğru yorum hangisidir?', 'Maliyet verimli ama programın gerisinde', ['Maliyet aşımı var ama program öndedir', 'Hem maliyet hem program planın gerisindedir', 'Her ikisi de planın ilerisindedir'], 'CPI > 1 harcamanın kazanılan değere göre az olduğunu, SPI < 1 işin planlanandan yavaş ilerlediğini gösterir.'),
  ('Bir riskin gerçekleşme olasılığı %20, gerçekleşirse maliyeti 50 000 TL ise beklenen parasal değeri (EMV) kaç TL\'dir?', '10 000', ['2 500', '30 000', 'Yaklaşık 70 000'], 'EMV = olasılık × etki = 0,20 × 50 000 = 10 000 TL\'dir.'),
  ('Bir inşaat firması, depremde hasar riskini sigorta poliçesiyle bir sigorta şirketine devrediyor. Bu risk yanıt stratejisinin adı nedir?', 'Transfer', ['Kaçınma', 'Azaltma, yani olasılığı düşürmek için ek önlem almak', 'Kabul'], 'Riskin sonuçlarının mali yükünü üçüncü bir tarafa aktarmak transferdir. Risk ortadan kalkmaz, yalnızca yükü paylaşılır.'),
  ('Yeni, denenmemiş bir teknolojiden vazgeçip kanıtlanmış eski teknolojiyi seçmek hangi risk yanıtına örnektir?', 'Kaçınma', ['Transfer', 'Kabul', 'Fırsatı artırma'], 'Riskin kaynağını tamamen ortadan kaldıracak şekilde planı değiştirmek kaçınma stratejisidir.'),
  ('Proje yöneticisi, olasılığı çok düşük ve etkisi küçük bir riski izleyip hiçbir önlem almamaya karar veriyor. Bu strateji hangisidir?', 'Kabul', ['Azaltma', 'Transfer', 'Kaçınma'], 'Riski kabul etmek, önlem için kaynak harcamadan oluşursa sonucuna katlanmaktır. Etkisi küçük risklerde yaygındır.'),
  ('Önlem uygulandıktan sonra geriye kalan risk ile önlemin kendisinin doğurduğu yeni risk sırasıyla nasıl adlandırılır?', 'Artık risk ve ikincil risk', ['Kabul riski ve doğal risk', 'Gizli risk ve açık risk', 'Yapısal risk ve geçici risk'], 'Artık (residual) risk yanıt sonrası kalan risktir; ikincil (secondary) risk ise yanıtın yarattığı yeni risktir.'),
  ('Bir proje ekibinde 10 kişi bulunuyor. İkili iletişim kanalı sayısı kaçtır?', '45', ['20', '90', '100'], 'Kanal sayısı n(n − 1)/2 = 10 × 9 / 2 = 45\'tir. Ekip büyüdükçe iletişim hızla karmaşıklaşır.'),
  ('Sprint sonunda ekibin kendi çalışma biçimini nasıl iyileştireceğini konuştuğu etkinlik hangisidir?', 'Sprint Retrospective', ['Sprint Review', 'Sprint Planning', 'Backlog Refinement, yani listenin ileri sprintler için düzenlenmesi'], 'Retrospective, süreç, araç ve ilişkilerde iyileştirme fırsatlarını belirler. Review ise ürün artışının paydaşlara gösterildiği toplantıdır.'),
  ('Kaynak dengeleme (resource leveling) uygulandığında projenin bitiş tarihi için ne beklenir?', 'Gecikebilir, çünkü kaynak sınırı etkinlikleri kaydırır', ['Her zaman erkene alınır, çünkü kaynaklar daha verimli kullanılır', 'Hiç değişmez', 'Yalnızca bütçe artar ve takvim hiç etkilenmez'], 'Dengeleme, aşırı yüklenmeyi gidermek için etkinlikleri kaydırır ve bolluk yetmezse kritik yolu uzatabilir.'),
  ('Tuckman\'a göre takım gelişiminde çatışmaların ve rol tartışmalarının yoğunlaştığı evre hangisidir?', 'Fırtına (storming)', ['Oluşum (forming)', 'Normlaşma (norming)', 'Performans (performing)'], 'Tuckman evreleri oluşum, fırtına, normlaşma ve performanstır. Fırtına evresinde roller ve yöntemler üzerinde sürtüşme yaşanır.'),
  ('Yapılandırma yönetiminin temel amacı nedir?', 'Ürünün sürümlerini ve kabul edilmiş durumunu izlenebilir biçimde kontrol etmek', ['Çalışanların maaşlarını ve izin günlerini belirlemek ve duyurmak', 'Ürünün pazarlama stratejisini çizmek', 'Tedarikçi seçmek'], 'Yapılandırma yönetimi, hangi sürümün onaylı olduğunu ve değişikliklerin nasıl yapıldığını kayıt altında tutar.'),
  ('Maliyet artı kâr (cost-plus) sözleşmede alıcının karşılaştığı temel risk nedir?', 'Nihai maliyetin belirsizliği ve yüklenicinin tasarruf etme isteğinin zayıflaması', ['Fiyatın hiç artamaması', 'Yüklenicinin tüm giderlerinin ödenmesi yüzünden hiçbir zaman kâr edememesi', 'Teslim süresinin sıfırlanması'], 'Cost-plus\'ta gerçek giderler ödenir; kapsam belirsiz olduğunda uygundur ama alıcı bütçe kontrolünü zorlaşır.'),
  ('Kapsamın tam belli olmadığı kısa bir danışmanlık işinde saat ücretiyle çalışılan sözleşme türü hangisidir?', 'Zaman ve malzeme (T&M)', ['Götürü bedel', 'Anahtar teslim', 'İhale şartnamesi (kapsamın ve fiyatın önceden kesin yazıldığı belge)'], 'T&M sözleşmesi harcanan süre ve malzeme üzerinden ödeme yapar; kapsamı netleşmemiş işlerde esneklik sağlar.'),
  ('\'Alınan dersler\' (lessons learned) kaydı ne zaman ve niçin tutulmalıdır?', 'Proje boyunca ve kapanışta, gelecekteki projelerde aynı hataları önlemek için', ['Yalnızca dava çıkarsa kanıt olarak', 'Yalnızca proje iptal edilirse suçlu aramak ve gerekçe oluşturmak için', 'Sadece muhasebe için'], 'Alınan dersler sürekli toplanır ve kapanışta derlenir; kurumsal bilgi birikimi olarak sonraki projelere aktarılır.'),
  ('Aşağıdan yukarı (bottom-up) tahminin en önemli özelliği nedir?', 'Her iş paketi ayrı tahmin edilip toplanır, genellikle en doğrudur ama zaman alır', ['Yalnızca üst yönetim bütçe için tek bir rakam verir ve ayrıntıya girilmez', 'Tahmin tamamen rastgeledir', 'Hiç ayrıntıya girilmez'], 'WBS\'nin en alt düzeyindeki tahminler yukarıya doğru toplanır; ayrıntılı olduğu için doğru ama emek yoğundur.'),
  ('Bir kontrol grafiğinde noktaların tamamı sınırlar içinde rastgele dağılıyorsa süreç için ne söylenir?', 'Yalnızca ortak (doğal) değişkenlik vardır; süreç istatistiksel kontrol altındadır', ['Süreç mutlaka şartnameye uygundur', 'Süreç şartnameyi karşılamadığı için müşteri iade edecektir', 'Süreç durdurulmalıdır'], 'Kontrol altında olmak, öngörülebilir olmak demektir ve ürünün şartnameye uyduğunu garanti etmez; o ayrı bir yeterlilik sorusudur.'),
  ('Bir takım tezgâhında takım aşındığında üretilen çap ölçüleri giderek büyüyüp tek yönlü bir eğilim gösteriyor. Bu değişkenliğin türü nedir?', 'Özel (atanabilir) neden', ['Ortak neden', 'Ölçüm hatası dışındaki tek neden yok', 'Rastgele doğal değişkenlik'], 'Takım aşınması gibi belirlenebilir ve giderilebilir bir neden özel nedendir; süreç kontrol dışına çıkar.'),
  ('Bir süreçte Cp yüksek ama Cpk düşükse en olası sebep nedir?', 'Süreç ortalaması tolerans merkezinden kaymıştır', ['Süreç değişkenliği çok yüksektir ve ölçüm sistemi hatalıdır', 'Ölçüm aleti hiç kullanılmamıştır', 'Şartname sınırlarının hiç belirlenmemiş olması'], 'Cp yalnızca yayılımı, Cpk ise merkezlenmeyi de gözetir. Cpk ≪ Cp ise ortalama merkezden uzaklaşmıştır.'),
  ('500 üründe toplam 30 kusur bulunmuş ve her üründe 4 kusur fırsatı vardır. DPMO kaçtır?', '15 000', ['60 000', '7 500', '1 500'], 'DPMO = kusur/(birim × fırsat) × 10⁶ = 30/(500 × 4) × 10⁶ = 15 000\'dir.'),
  ('Altı Sigma\'da var olan bir süreci değil, yeni bir ürün ya da süreci baştan tasarlamak için hangi yapı kullanılır?', 'DMADV', ['DMAIC', 'SIPOC, yani süreç girdi ve çıktılarını haritalayan araç', '5S'], 'DMADV (tanımla, ölç, analiz et, tasarla, doğrula) yeni tasarım içindir; DMAIC ise var olan süreci iyileştirir.'),
  ('Philip Crosby\'nin kalite anlayışını özetleyen \'sıfır hata\' yaklaşımı neyi savunur?', 'İşi ilk seferde doğru yapmak, hatayı kabul edilebilir saymamak', ['Müşteri şikâyetlerini yok saymak', 'Denetimi tamamen kaldırmak', 'Maliyeti her koşulda kalitenin üstünde tutmak, denetimi kaldırmak'], 'Crosby\'ye göre kalite uygunluktur, kaliteyi sağlamanın maliyeti hatanın maliyetinden düşüktür; \'Quality is Free\' (1979) kitabıyla bilinir.'),
  ('Kalite güvencesi (QA) ile kalite kontrol (QC) arasındaki fark nedir?', 'QA süreç odaklı ve önleyici, QC ürün odaklı ve hata bulmaya yöneliktir', ['QA yalnızca ölçüm yapar, QC yalnızca belgeler', 'QA yalnızca ölçüm yapar ve QC yalnızca dokümantasyon yönetir', 'QA ürünü teslimden sonra denetler, QC tasarımı onaylar'], 'Güvence hataların oluşmasını önleyecek süreci kurar, kontrol ise çıkan ürünü inceleyerek hataları yakalar.'),
  ('Yalın düşüncede \'değer akışı haritalaması\' ne işe yarar?', 'Malzeme ve bilgi akışını izleyip değer katmayan adımları ortaya çıkarır', ['Çalışanların maaş sıralamasını çıkarır', 'Yalnız makine yerleşimini çizer', 'Ürünün satış fiyatını ve kâr marjını belirleyip pazara duyurur'], 'Değer akışı haritası, müşteri talebinden teslimata kadar tüm adımları gösterir; bekleme ve stok gibi israf noktaları görünür olur.'),
  ('Çekme (pull) sistemi ile itme (push) sistemi arasındaki fark nedir?', 'Çekmede üretim, sonraki istasyonun talebiyle başlar', ['Çekmede üretim tahmine göre önceden yapılır', 'İtmede hiç planlama yoktur', 'Çekme yalnızca ağır sanayide ve yalnızca otomotivde kullanılabilir'], 'Çekme sistemi (kanban) arkadaki talep olmadan üretmez; itme sistemi ise tahmin ve plana göre ileri doğru üretir. Çekme fazla stoku azaltır.'),
  ('TPM (Toplam Verimli Bakım) uygulamasında \'otonom bakım\' neyi ifade eder?', 'Operatörün ekipmanın temizlik, yağlama ve basit kontrolünü üstlenmesi', ['Bakımın tamamen taşerona verilmesi', 'Makinelerin bakıma hiç gerek duymadan sürekli çalışmaları', 'Arıza olunca beklemek'], 'Otonom bakımda operatörler makinesinin sahibi gibi davranır; küçük anormallikleri erken fark ederek arızayı önler.'),
  ('Yüzde yüz muayene yerine örnekleme muayenesi hangi durumda zorunlu hâle gelir?', 'Muayenenin ürünü tahrip etmesi durumunda', ['Ürünün çok ucuz olması ve partinin küçük olması durumunda', 'Partinin hiç olmaması durumunda', 'Müşterinin istememesi durumunda'], 'Çekme testi ya da ömür testi gibi muayeneler ürünü tahrip eder; bu yüzden tüm parti değil örnek test edilir.'),
  ('Ürün müşteriye ulaşmadan fabrikada bulunan hatalar için yapılan yeniden işleme ve hurda giderleri hangi kalite maliyeti sınıfındadır?', 'İç hata maliyeti', ['Önleme maliyeti', 'Değerlendirme maliyeti', 'Dış hata maliyeti'], 'Hatanın müşteriye gitmeden fark edilip düzeltilmesinin maliyeti iç hata maliyetidir; garanti, iade ve itibar kaybı ise dış hata maliyetidir.'),
  ('Operatör eğitimi ve süreç tasarımı iyileştirmesi için yapılan harcamalar kalite maliyeti sınıflamasında nereye girer?', 'Önleme maliyeti, hata oluşmadan önleyen yatırımdır', ['İç hata maliyetine, çünkü iyileştirme fabrikada yapılır', 'Dış hata maliyetine, çünkü müşteriyi etkiler', 'Değerlendirme maliyetine, çünkü ölçüm içerir'], 'Önleme maliyeti hatayı oluşmadan engellemeye yönelik eğitim, planlama ve tasarım çalışmalarıdır; genelde en düşük getiri-maliyet oranı buradadır.'),
  ('\'1-10-100 kuralı\' hata düzeltme maliyeti konusunda ne söyler?', 'Hata ne kadar geç yakalanırsa düzeltme maliyeti o kadar katlanarak artar', ['Hata maliyeti aşamalardan bağımsızdır ve her aşamada aynı kalır', 'Müşteride bulunan hata en ucuz hatadır', 'Önleme en pahalı yoldur'], 'Kural, hatanın önlenmesi, üretimde yakalanması ve müşteride bulunması maliyetlerinin kabaca on kat basamaklarla büyüdüğünü anlatır.'),
  ('Bir fabrikada önleme 40, değerlendirme 60, iç hata 150, dış hata 250 bin TL ise toplam kalite maliyeti kaç bin TL\'dir?', '500', ['450', '300', '400'], 'Toplam = 40 + 60 + 150 + 250 = 500 bin TL\'dir. Hata maliyetleri (400) toplamın büyük bölümünü oluşturur.'),
  ('Deney tasarımında (DOE) tek seferde birden çok faktör değiştirilip etkileşimler incelenir. Bu yaklaşımın tek-tek faktör denemesine üstünlüğü nedir?', 'Faktörler arası etkileşimi ve daha az deneyle daha çok bilgiyi görmeyi sağlar', ['Hiç deney yapmayı gerektirmez', 'Yalnızca tek faktör için çalışır', 'Sonuçların her seferinde tamamen rastgele çıkmasını güvenceye alır'], 'Faktörlerin birlikte etkisi, tek tek denemelerle görülemez. Çok faktörlü tasarım hem etkileşimleri hem etkileri verimli biçimde ölçer.'),
  ('İki değişken arasında ilişki olup olmadığını noktalarla gösteren kalite aracı hangisidir?', 'Serpilme (dağılım) diyagramı', ['Kontrol listesi, yani verilerin sahada işaretlendiği form', 'Histogram', 'Balık kılçığı'], 'Serpilme diyagramında her ölçüm bir nokta olur; noktaların örüntüsü pozitif, negatif ya da hiç ilişki olmadığını gösterir.'),
  ('Bir cihaz 1000 saatlik çalışmada 5 kez arıza yapıyor ve her arızadan sonra onarılıyor. Ortalama arızalar arası süre (MTBF) kaç saattir?', '200', ['5', '1000', '500'], 'MTBF = toplam çalışma süresi/arıza sayısı = 1000/5 = 200 saattir.'),
  ('Üstel dağılımla modellenen, sabit arıza oranlı bir bileşenin arıza davranışı için ne söylenebilir?', 'Arıza olasılığı geçmiş çalışma süresine bağlı değildir', ['Yaşlandıkça arıza oranı artar ve kullanılan bileşen eskir', 'Yeni olduğunda arıza oranı çok yüksektir', 'Arıza hiç gerçekleşmez'], 'Sabit arıza oranı, bileşenin yaşından bağımsız arıza davranışı anlamına gelir; küvet eğrisinin yararlı ömür bölgesine karşılık gelir.'),
  ('Güvenilirliği 0,9 olan üç özdeş bileşenden ikisi çalışırsa sistem çalışıyor sayılan (2-of-3) yapının güvenilirliği yaklaşık kaçtır?', '0,972', ['0,729', '0,999', '0,810'], 'R = 3R²(1−R) + R³ = 3(0,81)(0,1) + 0,729 = 0,243 + 0,729 = 0,972\'dir.'),
  ('Kaynakta oluşan zararlı dumanı çekip dışarı atan yerel havalandırma sistemi hangi kontrol türüdür?', 'Mühendislik kontrolü', ['İdari kontrol', 'Kişisel koruyucu donanım', 'Eliminasyon'], 'Tehlikeyi işçiden ayıran fiziksel düzenlemeler (havalandırma, siperlik, kapama) mühendislik kontrolleridir.'),
  ('LOTO uygulamasında her bakım çalışanının kendi kilidini takmasının amacı nedir?', 'Makineyi yalnızca herkes işini bitirip kendi kilidini açtığında çalıştırılabilir kılmak', ['Kilit sayısını artırarak malzeme tüketmek', 'Yöneticinin makineyi denetlemesini kolaylaştırmak', 'Kilitlerin sıra ile numaralandırılması'], 'Kişisel kilit, çalışanın makinede çalışırken başkası tarafından enerjilenmemesini garanti eder; son kilit açılmadan enerji verilemez.'),
  ('Heinrich\'in domino modeline göre kaza zincirini önlemenin en etkili yolu nedir?', 'Zincirdeki dominolardan birini (güvensiz davranış/durum) çekip zinciri kırmak', ['Kazadan sonra yalnızca yaralılara tazminat ödeyip raporu arşive kaldırmak', 'Yaralıları hastaneye götürmek', 'Sigorta yaptırmak'], 'Heinrich\'e göre kazalar bir olay zincirinin sonucudur; zincirin ortasındaki güvensiz hareketler ya da durumlar giderilirse yaralanma oluşmaz.'),
  ('Heinrich\'in \'kaza piramidi\' 1:29:300 oranı neyi anlatır?', 'Bir ağır yaralanmaya karşı çok sayıda hafif ve yaralanmasız olay bulunduğunu', ['Her kazanın tam olarak 300 saatte sona ereceğini ve herkesin bundan etkileneceğini', 'Kaza maliyetinin 29 kat arttığını', '300 işçiden yalnızca birinin kaza geçireceğini'], 'Piramit, küçük olayların ağır kazaların habercisi olduğunu savunur. Bu yüzden ramak kala olayları kayıt altına alınmalıdır.'),
  ('Fine-Kinney yönteminde risk puanı hangi üç etkenin çarpımıyla bulunur?', 'Olasılık, frekans, şiddet', ['Maliyet, süre, kapsam', 'Güç, ilgi, etki', 'Tespit, kontrol, geri bildirim'], 'Fine-Kinney\'de risk = olasılık × maruz kalma sıklığı × şiddet; sonuç puan aralığına göre kabul edilebilir ya da acil önlem gerektiren sınıflara ayrılır.'),
  ('Olasılık 3, frekans 6, şiddet 7 olan bir tehlikenin Fine-Kinney risk puanı kaçtır?', '126', ['16', '90', '378'], 'Risk = 3 × 6 × 7 = 126\'dır.'),
  ('HAZOP çalışmasında \'kılavuz sözcükler\' (hayır, fazla, az gibi) ne için kullanılır?', 'Süreç parametrelerindeki olası sapmaları sistematik biçimde aramak için', ['Çalışanları işe almak için', 'Çalışanların yetkinliğini puanlayıp işe alma kararı vermek için', 'Bütçeyi bölüştürmek için'], 'HAZOP, her hat ya da cihaz için akış, basınç, sıcaklık gibi parametrelere kılavuz sözcükleri uygulayıp sapma nedenlerini ve sonuçlarını sorgular.'),
  ('Bir kimya tesisinde HAZOP ekibi \'Akış + Fazla\' kılavuz sözcüğüyle bir boru hattını inceliyor. Sorgulanan sapma nedir?', 'Beklenenden fazla akış', ['Hiç akış olmaması', 'Ters yönde akış', 'Başka bir sıvının akması'], '\'Fazla\' sözcüğü bir parametrede nicel artışı anlatır; ekip nedenleri (vana arızası) ve sonuçları (taşma, basınç) tartışır.'),
  ('\'What-if\' (ya olursa) analizinin temel özelliği nedir?', 'Ekibin serbest tartışmayla \'şu olursa ne olur\' sorularını sorması', ['Matematiksel formüller çözmesi', 'Karmaşık matematiksel denklem sistemlerini bilgisayarda çözmesi', 'Kâğıt üzerinde hiç not tutmaması'], 'What-if, uzman ekibin beyin fırtınasıyla olası sapmaları ve sonuçları sıraladığı yapılandırılmış ama esnek bir tehlike tanımlama tekniğidir.'),
  ('Makine siperinin açılınca tehlikeli hareketi durduran emniyet anahtarına ne ad verilir?', 'Kilitleme (interlock) anahtarı', ['Zaman rölesi', 'Sıcaklık sensörü', 'Sigorta'], 'Interlock, siper açıkken makinenin çalışmasını engeller; operatörü hareketli parçalarla temastan korur.'),
  ('Emniyet açısından \'tehlikeli arıza\' ile \'emniyetli arıza\' arasındaki fark nedir?', 'Tehlikeli arıza koruma fonksiyonunu devre dışı bırakır, emniyetli arıza sistemi güvenli duruma getirir', ['Tehlikeli arıza daha ucuzdur ve emniyetli arıza her zaman kaza yapar', 'Emniyetli arıza hep bakım gerektirir', 'İkisi arasında fark yoktur'], 'Bir korumanın tehlikede görev yapamaması tehlikeli arızadır. Gereksiz durdurma ise emniyetli ama üretimi aksatan arızadır.'),
  ('Yangın söndürücü kullanımında akılda tutulan PASS kısaltmasında \'S\' (Squeeze) neyi ifade eder?', 'Kolu sıkarak söndürücü maddeyi bırakmayı', ['Söndürücüyü yangına doğru fırlatmayı', 'Alarmı susturmayı', 'Kapıyı kapatmayı'], 'PASS: Pull (pimi çek), Aim (hortumu tabana doğrult), Squeeze (kolu sık), Sweep (yandan yana süpür).'),
  ('Yangın alarm sistemlerinde duman dedektörü ile ısı dedektörü arasındaki temel fark nedir?', 'Duman dedektörü yanma ürünü partiküllerini, ısı dedektörü sıcaklık artışını algılar', ['Isı dedektörü dumanı görür, duman dedektörü sıcaklığı', 'Isı dedektörü yalnızca dumanı görür, duman dedektörü yalnızca sıcaklığı algılar', 'İkisi de yalnızca sesi algılar'], 'Duman dedektörleri erken uyarı verir; mutfak ve garaj gibi dumanlı ortamlarda yanlış alarmı önlemek için ısı dedektörü seçilir.'),
  ('Gürültü düzeyi 3 dB artırılırsa ses enerjisi (güç) yaklaşık kaç kat olur?', 'İki kat', ['Üç kat', 'Yarısı kadar, yani yarıya iner', 'On kat'], 'Desibel logaritmiktir; her +3 dB yaklaşık enerji iki katı demektir. Bu yüzden sürelere sınır koyarken 3 dB değişimi esas alınır.'),
  ('El-kol titreşimine uzun süre maruz kalmanın tipik sağlık sorunu hangisidir?', 'Parmaklarda kan dolaşımı bozukluğu', ['Görme kaybı ve gözde kalıcı hasar', 'Kalp krizi', 'İşitme kaybı'], 'Pnömatik el aletleri gibi titreşimli aletler damar ve sinir hasarına yol açabilir; vücut titreşimi ise bel ağrılarıyla ilişkilidir.'),
  ('Kapalı alanda çalışan kişi baygın bulunursa kurtarma için ne yapılmamalıdır?', 'Solunum cihazı olmadan kendiliğinden içeri girmek', ['Dışarıdan alarm vermek', 'Kurtarma ekibini çağırmak', 'Havalandırmayı sağlayıp ortamı ölçtürmek'], 'Kapalı alan ölümlerinin büyük bölümü kurtarmaya giden ikinci kişilerin aynı atmosferde zehirlenmesidir; hazırlıksız girilmez.'),
  ('Yüksekte çalışmada düşme durdurma sisteminin hangi bileşeni çalışanı sabit bir bağlantı noktasına bağlar?', 'Lanyard (bağlantı halatı) ve çengel', ['Baret çene bağı ve ayarlanabilir iç iskelet', 'Eldiven', 'Kulak tıkacı'], 'Tam vücut emniyet kemeri, bağlantı elemanı ve sağlam bir bağlantı noktasından oluşan sistem düşmeyi durdurur.'),
  ('GHS sisteminde kimyasalın tehlike derecesini \'Tehlike\' ve \'Dikkat\' kelimeleri ile belirten etiket öğesi nedir?', 'Uyarı sözcüğü', ['Piktogram', 'Parti numarası', 'Barkod'], 'GHS etiketinde uyarı sözcüğü, ciddi tehlikeler için \'Tehlike\', daha hafif olanlar için \'Dikkat\'tır.'),
  ('GHS piktogramlarında beyaz zemin üzerinde kırmızı çerçeveli, ortasında alev bulunan sembol hangi tehlikeyi gösterir?', 'Yanıcılık', ['Aşındırıcılık', 'Çevreye zararlılık', 'Gaz basıncı altında olma'], 'Alev piktogramı yanıcı gaz, sıvı, katı ve kendiliğinden ısınan maddeleri gösterir; kafatası-çapraz kemik ise akut zehirliliği belirtir.'),
  ('Birbiriyle tehlikeli tepkimeye girebilen kimyasalların (asit ve baz gibi) depolanmasında hangi ilke uygulanır?', 'Uyumsuz maddeler ayrı bölümlerde saklanır', ['Tüm kimyasallar tek rafta alfabetik sırayla yan yana saklanır', 'Alfabetik sırayla yan yana konur', 'Fiyatlarına göre sıralanır'], 'Depolamada alfabetik sıralama yerine tehlike sınıfına göre ayrım yapılır; böylece sızıntı durumunda tepkime riski azalır.'),
  ('Alçak gerilim ve çok küçük koruyucu gerilim kavramı için alternatif akımda genellikle hangi üst sınır kullanılır?', '50 V', ['230 V', '400 V', '1000 V'], 'Kuru ortamda 50 V AC altı \'ek düşük gerilim\' sayılır; ıslak ve iletken ortamlarda daha düşük gerilimler tercih edilir.'),
  ('Elektrik çarpmasında vücuttan geçen akımın şiddeti ve süresi sonuçları nasıl etkiler?', 'Akım ve süre arttıkça kalp fibrilasyonu riski artar', ['Yalnızca gerilim önemlidir', 'Süre hiç önemli değildir, yalnızca gerilim belirleyicidir', 'Akım ne olursa olsun zarar vermez'], 'Yaralanmanın ağırlığı vücut direncine, akım yoluna, akım şiddetine ve süresine bağlıdır; birkaç on miliamper bile solunum ve kalp ritmini bozabilir.'),
  ('Patlayıcı ortam (gaz, buhar, toz) bulunan yerlerde kullanılacak elektrikli ekipmanlar için hangi Avrupa direktifi geçerlidir?', 'ATEX', ['RoHS', 'CE saat', 'EMC yalnızca'], 'ATEX direktifleri patlayıcı atmosferlerde kullanılan ekipmanın kıvılcım ve sıcak yüzey riskleri bakımından uygunluğunu düzenler.'),
  ('İşyerinde tekrarlayan hareketlerle ortaya çıkan ve karpal tünel sendromunu da kapsayan sağlık sorunu grubu nasıl adlandırılır?', 'Kas-iskelet sistemi rahatsızlıkları', ['Mesleki asma', 'Radyasyon yanıkları', 'Dekompresyon hastalığı ve kulak zarı hasarları'], 'Tekrarlı hareket, zorlu duruş ve kuvvet uygulaması kas, tendon ve sinirlerde birikimli hasara yol açar; bu tablo kas-iskelet sistemi rahatsızlıklarıdır.'),
  ('Tasarım incelemesi (design review) toplantısının başlıca amacı nedir?', 'Tasarımı erken aşamada bağımsız gözle sorgulayıp hataları üretimden önce yakalamak', ['Ürünün reklamını yapmak', 'Yöneticilerin maaşını belirlemek', 'Çalışanların izin günlerini planlamak'], 'Tasarım incelemeleri farklı disiplinlerden kişilerle yapılır; değişiklik maliyetinin düşük olduğu aşamada sorunları ortaya çıkarır.'),
  ('Fail-safe yerine \'safe-life\' tasarım yaklaşımı ne demektir?', 'Parçanın belirli bir ömür boyunca çatlaksız çalışacağı varsayılıp o ömürde değiştirilmesi', ['Parça arızalansa bile yük başka yollardan taşınır', 'Parça hiç bakım istemez ve ömrü boyunca hiçbir kontrole gerek duymaz', 'Parça asla tasarım yükünden fazlasına maruz kalmaz'], 'Safe-life, öngörülen ömür sonunda parçayı bir kontrol yapılmaksızın değiştirmeyi gerektirir; fail-safe ise yedek yük yolu bırakır.'),
  ('Titreşim analizi ve yağ analiziyle ekipmanın durumunu izleyip bozulma belirtisinde müdahale etmek hangi bakımdır?', 'Kestirimci (durum izlemeli) bakım', ['Arıza sonrası bakım', 'Takvime bağlı koruyucu bakım', 'Otonom bakım'], 'Kestirimci bakım parçanın gerçek durumuna bakar, gereksiz parça değişimini azaltır ve plansız duruşları önler.'),
  ('Rulmanın 5000 çalışma saatinde, durumuna bakılmaksızın değiştirilmesi hangi bakım türüdür?', 'Zamana bağlı koruyucu bakım', ['Kestirimci bakım, yani titreşim ve yağ analizine dayalı bakım', 'Arıza sonrası bakım', 'Geliştirici bakım'], 'Sabit aralıkla yapılan önleyici değişimler zamana dayalı koruyucu bakımdır. Sağlam parçaları da değiştirme riski taşır.'),
  ('Güvenilirlik merkezli bakımın (RCM) temel sorusu hangisidir?', 'Her varlığın işlevini yitirmesinin sonuçları nelerdir ve hangi bakım görevi bunu etkili önler?', ['En ucuz yedek parça hangisidir?', 'Yedek parça stokunun en düşük maliyetle nasıl tutulacağı ve kimden alınacağı', 'Makine kaç yıl önce satın alınmıştır?'], 'RCM, varlığın işlevi ve arıza sonuçları üzerinden bakım görevlerini seçer; yalnız parça yaşına bakmaz.'),
  ('Yönetimin güvenliğe gerçek bağlılığının en güçlü göstergesi hangisidir?', 'Üretim baskısı altında bile güvenlik için işi durdurmaya izin vermesi', ['Duvara güvenlik afişi asıp yıl sonunda tebrik mesajı yayımlaması', 'Yıllık bir konuşma yapması', 'Kazaları rakamlarla göstermesi'], 'Davranışlar sözlerden önemlidir. Çalışanın güvenlik nedeniyle işi durdurma yetkisi, kültürün somut bir göstergesidir.'),
  ('\'Güvenlik önce\' sloganı hakkında hangisi doğrudur?', 'Slogan ancak kaynak, eğitim ve karar yetkisiyle desteklenirse işe yarar', ['Slogan tek başına kazaları sıfırlar', 'Slogan çalışanlar için bağlayıcı bir yasadır', 'Slogan ancak yöneticiler için geçerlidir'], 'Etkili bir kültür, söylemin ötesinde bütçe, süre ve yetkiyle somutlaşır; yalnızca afiş davranışı kalıcı olarak değiştirmez.'),
  ('Kök neden analizinde \'insan hatası\' tek başına son neden olarak yazılırsa ne sorun doğar?', 'Süreç, eğitim, tasarım gibi sistemik nedenler incelenmeden kalır', ['Raporun çok uzaması', 'Çalışan sayısının artması', 'Bütçenin fazlalaşması ve soruşturma ekibinin büyümesi'], 'İnsan hatası çoğu zaman belirtidir; neden bu hatanın mümkün olduğu (tasarım, iş yükü, talimat) sorulmalıdır.'),
  ('Düzeltici faaliyet ile önleyici faaliyet arasındaki fark nedir?', 'Düzeltici mevcut uygunsuzluğun nedenini giderir, önleyici henüz olmamış olası uygunsuzluğu önler', ['İkisi de aynı anlama gelir', 'Düzeltici yalnızca belge yazar', 'Düzeltici yalnız üretim hattında, önleyici yalnız satış biriminde uygulanır'], 'Düzeltici faaliyet gerçekleşmiş sorunun tekrarını önler; önleyici faaliyet potansiyel sorunu önceden engeller.'),
  ('Bir projenin iş ilerleme yüzdesi %40, bütçesi (BAC) 200 bin TL ise kazanılmış değer (EV) kaç bin TL\'dir?', '80', ['40', '200', '120'], 'EV = ilerleme yüzdesi × BAC = 0,40 × 200 = 80 bin TL\'dir.'),
  ('Proje yönetiminde \'kapsam doğrulama\' (scope validation) neyi ifade eder?', 'Teslim edilen çıktıların müşteri tarafından resmen kabul edilmesi', ['Çıktıların ekip içinde kendi kendine test edilmesi', 'Bütçenin muhasebe tarafından onaylanması', 'Takvimin müşteri dışındaki bir taraf tarafından imzalanması'], 'Kalite kontrol çıktının doğruluğunu iç olarak sınar; kapsam doğrulama müşteri kabulüdür.'),
  ('Net bugünkü değer (NPV) pozitif çıkan bir yatırım projesi için hangisi söylenebilir?', 'İskonto oranında nakit akışlarının bugünkü değeri maliyeti aşıyor', ['Proje mutlaka zarar edecektir', 'Proje bedavadır', 'Getirisi hiç hesaplanamaz ve karar için yeterli bilgi vermez'], 'Pozitif NPV, gelecekteki net nakit girişlerinin bugünkü değerinin yatırım maliyetinden büyük olduğunu gösterir.'),
  ('Yatırım 1000 TL; 1 yıl sonra 1100 TL getirecek. İskonto oranı %5 ise NPV yaklaşık kaç TL\'dir?', '47,6', ['100', '-47,6', '10 yıl sonra elde edilecek tutarın 1000 TL\'ye bölünmesiyle bulunan 1,1'], 'NPV = 1100/1,05 − 1000 = 1047,6 − 1000 = 47,6 TL\'dir.'),
  ('Yatırım maliyeti 600 bin TL ve yıllık net kazanç 150 bin TL olan projenin basit geri ödeme süresi kaç yıldır?', '4', ['3', '6', '0,25 yıl, çünkü 150 bin TL yatırımın dörtte biridir ve yıllık hesap yapılmaz'], 'Geri ödeme = yatırım/yıllık kazanç = 600/150 = 4 yıldır. İskonto etkisi dikkate alınmaz.'),
  ('Scrum\'da \'Done tanımı\' (Definition of Done) ne işe yarar?', 'Bir ürün parçasının bitmiş sayılması için ortak ölçütü belirler', ['Sprint süresini belirler', 'Ürün sahibinin maaşını belirler', 'Toplantıların saatini ve katılımcı sayısını yalnızca yönetimin seçmesini sağlar'], 'Done tanımı, takımın \'bitti\' kavramında ortak bir anlayışa sahip olmasını sağlar; böylece artış kalite açısından şeffaf olur.'),
  ('Bir ekip sprint planlamada 8 görev seçti: 3 görev 5 puan, 5 görev 3 puan değerinde. Sprint için taahhüt edilen toplam hikâye puanı kaçtır?', '30', ['24', '8', 'Puanlar yerine yalnızca görev sayısı olan 8 üzerinden hesap yapılır'], '3 × 5 + 5 × 3 = 15 + 15 = 30 puandır.'),
  ('Kullanıcı hikâyesi (user story) genellikle hangi kalıpla yazılır?', '\'Bir [rol] olarak [amaç] istiyorum, böylece [değer]\'', ['\'Madde 1, Madde 2, Madde 3\' biçiminde sıra numaralı liste', 'Sözleşme maddeleri biçiminde hukuki dille', 'Hata kaydına benzer şekilde yalnızca teknik çözümü anlatan kısa bir not'], 'Kullanıcı hikâyesi, işlevi kullanıcının bakış açısıyla ve sağlayacağı değerle birlikte kısaca anlatır.'),
  ('Kanban panosunda bir iş kartının \'Yapılıyor\' sütununda çok uzun süre kalması neyi gösterir?', 'Akışta bir darbogaz ya da engel olabileceğini', ['Ekibin çok verimli olduğunu', 'İşin zaten bittiğini', 'Kartın yanlış renkle yazıldığını ve işin hiç başlamadığını'], 'Uzun bekleyen kartlar tıkanıklığı ya da bağımlılığı gösterir; WIP limiti ve akış metrikleri bu noktaları görünür kılar.'),
  ('Çevik yaklaşımlarda \'MVP\' (en az uygulanabilir ürün) neyi anlatır?', 'Öğrenmek için müşteriye sunulabilecek en küçük işlevsel ürün', ['En pahalı ürün', 'En çok özellik içeren ürün', 'Tüm olası özelliklerin birden eklendiği kapsamlı ürün ve belgelendirilmiş son hâli'], 'MVP, hipotezleri en az emekle sınamak için piyasaya sürülen asgari işlevli üründür; geri bildirim sonraki adımları yönlendirir.'),
  ('Çevik ekiplerde \'teknik borç\' ne demektir?', 'Hızlı çözüm için bırakılan, sonradan düzeltilmesi gereken kalite eksikleri', ['Bankadan alınan kredi', 'Müşterinin ödemesi gereken faturalar', 'Tedarikçiye ödenmemiş malzeme bedeli ve yaklaşan vadeler'], 'Teknik borç, kısa yolların biriktirdiği ve zamanla değişim maliyetini artıran tasarım ve kod eksikliklerini anlatır.'),
  ('V modelinde \'doğrulama\' (verification) ve \'geçerleme\' (validation) arasındaki ayrım nedir?', 'Doğrulama ürünü doğru yapıyor muyuz, geçerleme doğru ürünü mü yapıyoruz sorusudur', ['İkisi aynı sorudur', 'Doğrulama müşteri kabulü, geçerleme kod incelemesidir', 'Doğrulama yalnızca montajdan sonra yapılır ve geçerleme hiç yapılmaz'], 'Doğrulama şartnameye uygunluğu, geçerleme ise ürünün gerçek kullanıcı ihtiyacını karşılayıp karşılamadığını sınar.'),
  ('Bir etkinlik 120 adam-saat iş gerektiriyor ve 4 kişi günde 6 saat çalışacak. Kaç gün sürer?', '5', ['20', '30', '10 gün, çünkü adam-saatten kişi sayısı çıkarılarak gün hesaplanır'], 'Günlük kapasite 4 × 6 = 24 adam-saattir; 120/24 = 5 gündür.'),
  ('Süreç ortalaması 50 ve süreç standart sapması 2 olan bir sürecin bireysel değerler (X) grafiğinde, 3 sigma sınırlarıyla üst kontrol sınırı (UCL) kaçtır?', '56', ['52', '54', '60'], 'Kontrol sınırı ortalama + 3σ = 50 + 6 = 56\'dır.'),
  ('Alt grup boyutu 4, süreç σ değeri 2 olan X-bar grafiğinde ortalamaların standart hatası kaçtır?', '1', ['2', '0,5', '8, çünkü alt grup boyutu standart sapma ile çarpılır'], 'Ortalamaların standart sapması σ/√n = 2/√4 = 1\'dir. Bu yüzden X-bar sınırları bireysel sınırlardan dardır.'),
  ('Kontrol grafiğinde kontrol sınırlarının kullanıcının istediği şartname sınırlarına çekilmesi neden yanlıştır?', 'Sınırlar sürecin kendi doğal davranışını yansıtmalıdır', ['Şartname sınırları daha doğrudur', 'Sınırların kesin değeri yoktur', 'Sınırlar her ay sıfırdan seçildiğinde yeterlilik hesabı gereksiz hâle gelir ve kararlılık kavramı kalkar'], 'Kontrol sınırları süreçten hesaplanır; müşteri isteği ile değiştirilirse süreç kararlılığı izlenemez.'),
  ('Pp ve Ppk gibi performans indeksleri Cp ve Cpk\'den hangi açıdan ayrılır?', 'Uzun vadeli toplam değişkenliği kullanırlar', ['Yalnızca nitel veri kullanırlar', 'Şartname sınırı gerektirmezler', 'Alt grup içi kısa vadeli sapmayı yalnızca bir kez ve tek ölçümle hesaplarlar'], 'Cp/Cpk kısa vadeli (alt grup içi) sigma, Pp/Ppk ise tüm veriden hesaplanan genel sigma ile bulunur.'),
  ('Bir kabul planında n = 50 ve kabul sayısı c = 1\'dir. Örnekte 2 hatalı bulunursa parti için karar nedir?', 'Parti reddedilir', ['Parti kabul edilir', 'Parti yeniden örneklenmeden kabul', 'Karar verilemez, çünkü n sayısı yetersizdir ve ilave örnek her zaman zorunludur'], 'Hatalı sayısı (2), kabul sayısını (1) aştığından parti reddedilir.'),
  ('İlk parça muayenesi (first article inspection) ne zaman yapılır?', 'Yeni bir ürün ya da kalıp değişiminden sonra ilk üretilen parçada', ['Her gün sonunda', 'Yalnızca müşteri şikâyetinde', 'Her vardiyada rastgele seçilen son parçalar paketlenmeden önce yalnızca ambalaj kontrolü olarak'], 'İlk parça muayenesi, üretim tam hızla başlamadan tasarım ve kurulumun şartnameye uygun olduğunu doğrular.'),
  ('ISO 9001\'de \'Plan-Do-Check-Act\' ile birlikte kullanılan ve riskleri ele alan yaklaşım nasıl adlandırılır?', 'Risk temelli düşünme', ['Sıfır risk politikası', 'Risk gizleme', 'Her riskin sigorta ile karşılanması ve herhangi bir önlemin gereksiz görülmesi'], 'ISO 9001:2015, planlamada risk ve fırsatların belirlenmesini şart koşarak risk temelli düşünmeyi sistemin parçası yapar.'),
  ('Bir yönetim sistemi standardında \'iç tetkik\' (internal audit) kim tarafından yapılır?', 'Kuruluşun kendi görevlendirdiği, denetlediği alandan bağımsız personel', ['Yalnızca devlet memurları', 'Müşteri', 'Denetlenen alanın sorumlusu kendi çalışmalarını belgelendirerek kendi imzasıyla kapatır'], 'İç tetkik, sistemin işleyişini kuruluşun kendi eliyle ama bağımsız kişilerle denetleyen ve iyileştirme fırsatı bulan faaliyettir.'),
  ('Sertifikasyon denetiminde \'majör uygunsuzluk\' neyi ifade eder?', 'Sistemin temel şartının yerine getirilmemesi ya da ciddi bir sistem başarısızlığı', ['Yazım hatası', 'Önerilen bir iyileştirme', 'Küçük bir etiketin bir noktada eksik ya da yanlış yerleştirilmesi gibi tek seferlik kusurlar'], 'Majör uygunsuzluk sistemin amacına ulaşma yeteneğini zedeleyen bir eksikliktir; giderilmeden sertifika verilmez ya da askıya alınır.'),
  ('\'Kalıntı risk\' (residual risk) iş güvenliğinde ne anlama gelir?', 'Kontrol önlemleri uygulandıktan sonra geriye kalan risk', ['Hiç değerlendirilmemiş risk', 'Çalışan tarafından kabul edilmeyen risk', 'Önlemin kendisinin doğurduğu ikinci bir tehlike olan, işyerine sonradan eklenen ek risk'], 'Kalıntı risk, uygulanan önlemlerden sonra kalan risktir; kabul edilebilir düzeyde olup olmadığı yeniden değerlendirilir.'),
  ('Kulak tıkacı ile kulaklık (kulak koruyucu) tercihinde SNR değeri neyi ifade eder?', 'Koruyucunun tek sayılı ortalama ses azaltma değerini', ['Koruyucunun fiyatını ve ambalajındaki üretim tarihini', 'Ağırlığı', 'Rengin görünürlük sınıfını ve kulağa uygun boyutu'], 'SNR, işitme koruyucunun azaltabileceği ses düzeyini desibel olarak veren tek sayılı değerdir; yüksek SNR daha çok azaltma demektir.'),
  ('Çalışma izni (permit to work) sisteminin temel amacı nedir?', 'Tehlikeli işlerin kontrollü, yetkili ve önlemleri belgelenmiş biçimde yapılmasını sağlamak', ['Çalışanın işe devamını kontrol etmek', 'Maaş hesaplamak', 'İşin süresi ve ücretinin müşteriyle önceden pazarlıkla belirlenmesini sağlamak'], 'İzin sistemi; sıcak iş, kapalı alan gibi işlerde tehlike tanımı, önlemler ve onay zincirini yazılı güvence altına alır.'),
  ('İş güvenliği analizinde (JSA) bir işin adım adım incelenmesinin amacı nedir?', 'Her adımın tehlikelerini belirleyip önlem planlamak', ['İşi daha uzun süreye yaymak', 'Çalışanları denetlemek ve ceza kesmek', 'İşin ücretini ve ek mesai karşılığını adımlara göre belirlemek'], 'JSA, işi görevlere bölüp her görevin tehlikesini ve kontrolünü tanımlayarak kazaları öngörü ile önler.'),
  ('Bir şirkette 3 kayıp günlü kaza oldu ve toplam 1 500 000 saat çalışıldı. 1 milyon saat başına kayıp günlü kaza sıklığı (LTIFR) kaçtır?', '2', ['0,5', '4,5', '1,5, çünkü kaza sayısı yarım milyon saate bölünmüştür'], 'LTIFR = kaza sayısı × 10⁶ / çalışılan saat = 3 × 10⁶ / 1,5 × 10⁶ = 2\'dir.'),
  ('Kaza sıklık oranı gibi \'geriden gelen\' göstergelerin zayıflığı nedir?', 'Zarar gerçekleştikten sonra ölçüldüğü için önleyici yön göstermez', ['Hiç sayısal olmaması', 'Çok pahalı olması', 'Küçük şirketlerde yasal olarak kullanılamaması ve yalnızca devlet kurumlarınca hesaplanması'], 'Kaza sayıları olay olduktan sonra çıkar; ramak kala ve denetim bulguları gibi \'öncü\' göstergeler ise riski önceden gösterir.'),
  ('İki el kumandası (two-hand control) hangi amaçla kullanılır?', 'Operatörün ellerinin tehlikeli bölgede olmadığını garanti etmek', ['Makineyi hızlandırmak', 'İşi iki kişiye bölmek', 'Makineyi her an yöneticinin uzaktan kontrol edebilmesi için ek bir kanal sağlamak'], 'İki düğmeye aynı anda basılması gerektiğinden eller kumanda noktasında tutulur; tehlikeli hareket sırasında eller bölge dışında kalır.'),
  ('Bir makinenin tehlikeli bölgesini kapatan, açılması için alet gerektiren sabit siperin üstünlüğü nedir?', 'Operatörün kasten ya da yanlışlıkla devre dışı bırakmasını güçleştirmesi', ['Daha hızlı üretim sağlaması', 'Ağırlığı azaltması', 'Makine görünümünü iyileştirip pazarlama değerini yükseltmesi'], 'Sabit siperler koruyucu önlemin en basit ve güvenilir biçimidir; erişim gerektiren yerlerde kilitli siper tercih edilir.'),
  ('Yanıcı gazlarda \'alt patlama sınırı\' (LEL) neyi ifade eder?', 'Havada patlayıcı karışım oluşturan en düşük gaz derişimini', ['Gazın kaynama noktasını', 'Gazın en yüksek yoğunluğunu', 'Gazın depolama kabında en çok doldurulabileceği hacim yüzdesini'], 'Gaz derişimi LEL\'in altındayken karışım çok seyrektir ve tutuşmaz; LEL ile UEL arası patlayıcı aralıktır.'),
  ('Bir sıvının \'parlama noktası\' (flash point) neyi ifade eder?', 'Yüzeyinde kıvılcımla tutuşabilecek buhar oluşturduğu en düşük sıcaklığı', ['Kaynama sıcaklığını', 'Donma sıcaklığını', 'Kendiliğinden alev alma sıcaklığını ve yangının yayıldığı en yüksek ısıyı'], 'Parlama noktası düşük sıvılar (benzin gibi) oda sıcaklığında bile tutuşabilir buhar çıkarır, daha tehlikelidir.'),
  ('Güvenilirlik, mühendislikte hangi olasılık olarak tanımlanır?', 'Bir ürünün belirli koşullarda belirli süre işlevini yerine getirme olasılığı', ['Ürünün fiyatının düşük olma olasılığı', 'Ürünün satılma olasılığı', 'Ürünün her koşulda hiç bakım görmeden sonsuza dek çalışacağının güvencesi'], 'Güvenilirlik R(t), ürünün t süresi boyunca belirtilen koşullarda arızasız çalışma olasılığıdır.'),
  ('Elektronik bileşenlerde sıcaklık yükseldikçe arıza oranı genellikle nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Önce sıfıra iner ve sonra sabit kalır'], 'Yüksek sıcaklık kimyasal yaşlanma ve difüzyon süreçlerini hızlandırır; Arrhenius ilişkisi arıza hızının sıcaklıkla arttığını gösterir.'),
  ('\'Ortak neden arızası\' (common cause failure) yedekli sistemler için neden tehlikelidir?', 'Yedek bileşenlerin tamamını aynı anda etkileyip yedekliliğin kazancını yok edebilir', ['Yalnızca tek bileşeni etkiler', 'Yalnızca bakımı kolaylaştırır', 'Bileşenlerin yalnızca fiyatını artırır ve ek tedarik süresi gerektirir'], 'Aynı güç kaynağı, yangın ya da yazılım hatası gibi ortak neden, bağımsızlık varsayımını bozar ve yedekleri birlikte devre dışı bırakır.'),
  ('Kusur ayıklama (burn-in) uygulaması hangi dönemde ortaya çıkan arızaları elemeyi amaçlar?', 'Erken (bebek ölümü) arızaları', ['Aşınma arızaları', 'Rastgele arızaları', 'Ömür sonunda görülen tüm yorulma arızaları'], 'Burn-in, ürünleri müşteriye göndermeden önce çalıştırarak zayıf birimlerin ilk dönemde arıza vermesini sağlar.'),
  ('Süreç FMEA\'sı (PFMEA) ile tasarım FMEA\'sı (DFMEA) arasındaki fark nedir?', 'DFMEA tasarım kaynaklı, PFMEA üretim sürecinden kaynaklanan hata türlerini inceler', ['İkisi aynıdır', 'DFMEA yalnızca yazılım için, PFMEA yalnızca donanım içindir', 'PFMEA satış sürecini, DFMEA ise yalnızca tedarik zincirinin nakliyesini kapsar'], 'DFMEA ürünün tasarımındaki zayıflıkları, PFMEA ise imalat ve montaj adımlarındaki hata modlarını analiz eder.'),
  ('Kontrol planı (control plan) ne işe yarar?', 'Kritik özelliklerin nasıl, ne sıklıkla ve hangi yöntemle kontrol edileceğini belgeler', ['Satış hedeflerini belirler', 'Personelin izin günlerini planlar', 'Ürünün pazarlama kampanyasını planlar ve reklam bütçesini belirler'], 'Kontrol planı, FMEA\'da belirlenen risklere karşı üretimde uygulanacak ölçme ve izleme faaliyetlerini özetler.'),
  ('Ürün izlenebilirliği (traceability) neden önemlidir?', 'Hatalı parti bulununca etkilenen ürünlerin hızla belirlenip geri çağrılabilmesi için', ['Reklam yapmak için', 'Fiyatı düşürmek için', 'Parti numarası verildiği için ürün vergisinin düşük hesaplanması için'], 'Parti ya da seri numarasıyla geriye ve ileriye izleme, sorunlu ürünün kapsamını daraltır ve geri çağırma maliyetini azaltır.'),
  ('İki seviyeli 4 faktörlü bir tam faktöriyel deney kaç koşuldan oluşur?', '16', ['8', '4', '24, çünkü dört faktör sırayla çarpılır ve her faktör için dört seviye alınır'], 'Tam faktöriyelde koşul sayısı 2⁴ = 16\'dır.'),
  ('Sıcak ortamlarda çalışanlarda ısı stresini azaltmak için hangi önlem etkilidir?', 'Düzenli su içmek ve dinlenme araları vermek', ['Hiç mola vermemek', 'Koyu renk kalın giysi giymek', 'Sıvı alımını sınırlayıp terlemeyi yalnızca tuzlu içecekle telafi etmek'], 'Yeterli sıvı, gölge dinlenme noktaları ve çalışma-dinlenme düzenlemesi sıcak çarpmasını önler.'),
  ('Vardiyalı ve özellikle gece çalışmasının sağlık ve güvenlik açısından başlıca riski nedir?', 'Uyku bozukluğu ve yorgunluğa bağlı dikkat kaybı', ['Ses artışı', 'Maaşın azalması', 'Aydınlatma lüksünün sıfıra inmesi ve görme yetisinin kalıcı kaybı'], 'Sirkadiyen düzenin bozulması yorgunluğu artırır; kaza ve hata riski özellikle gece saatlerinde yükselir.'),
  ('Antropometrik veriler tasarımda \'uç kişilere göre tasarım\' yaklaşımı hangi durumda uygulanır?', 'Boşluk ve erişim için büyük kişiye, ulaşma mesafesi için küçük kişiye göre', ['Her zaman ortalamaya göre', 'Hiç uygulanmaz', 'Her ürünün yalnızca en küçük boylu çalışana göre çok sıkı biçimde üretilmesi'], 'Kapı yüksekliği gibi boşluklar büyük kişiye, kumanda erişimi gibi ulaşma mesafeleri küçük kişiye göre belirlenir; ayarlanabilirlik çözüm olabilir.'),
  ('\'Kademeli tasarım incelemesi\' (stage gate) süreçlerinde her kapının amacı nedir?', 'Bir sonraki aşamaya geçmeden önce kriterlerin karşılandığını doğrulamak', ['Üretimi hızlandırmak', 'Çalışan sayısını artırmak', 'Ürün fiyatının belirlenip kâr marjının önceden bildirilmesi'], 'Stage-gate, her aşama sonunda karar toplantısı yaparak devam, durdurma veya değiştirme kararı verir.'),
  ('Prototip testinin tasarım sürecindeki rolü nedir?', 'Varsayımları gerçek koşullarda sınayıp eksikleri üretimden önce göstermek', ['Ürünü satmak', 'Belgeleri azaltmak', 'Tasarımın tamamlandığını bildirip değişiklik kapısını kapatmak'], 'Prototip, hesap ve simülasyonla görülemeyen sorunları ucuza ortaya çıkarır; tasarım güvenini artırır.'),
  ('Tasarımda \'artıklık\' (redundancy) ile \'çeşitlilik\' (diversity) arasındaki fark nedir?', 'Artıklık aynı işlevi yapan yedekler, çeşitlilik farklı yöntemle yapan yedeklerdir', ['İkisi aynıdır', 'Artıklık yalnızca yazılım, çeşitlilik yalnızca donanımdır', 'Artıklık ucuz, çeşitlilik pahalı yedek anlamına gelir ve başka fark yoktur'], 'Farklı teknolojiyle yapılan yedekler ortak neden arızasına karşı daha dirençlidir.'),
  ('Bir hatta günlük net çalışma süresi 27 000 saniye, müşteri talebi günde 450 adettir. Takt süresi kaç saniyedir?', '60', ['27', '450', '170 saniye, çünkü toplam süre ve talep toplanarak bölünür'], 'Takt süresi = kullanılabilir süre / talep = 27 000/450 = 60 saniyedir. Üretim müşteri hızına göre ayarlanır.'),
  ('Yalın düşüncede \'tek parça akışı\' (one-piece flow) büyük partilere göre ne avantaj sağlar?', 'Hataların hızla fark edilmesini ve bekleme süresinin azalmasını', ['Stokun artmasını', 'Daha çok taşıma yapılmasını', 'Daha uzun hazırlık süresi gerektirip kalıp değişimini ayda birkaç kez yapmayı'], 'Küçük parti, hatalı parçaların kuyruğunda uzun bekleme olmadan sonraki istasyonda fark edilmesini ve toplam akış süresinin kısalmasını sağlar.'),
  ('Bir projede riskin \'tetikleyicisi\' (trigger) nedir?', 'Riskin gerçekleşmek üzere olduğunu gösteren erken uyarı belirtisi', ['Riskin maliyeti', 'Riskin sahibi', 'Riskin tamamen ortadan kalktığının onaylandığı kapanış belgesi'], 'Tetikleyiciler izlenerek yanıt planı zamanında devreye alınır; örneğin tedarikçinin gecikmeye başlaması teslimat riskinin tetikleyicisidir.'),
  ('Nitel risk analizi ile nicel risk analizi arasındaki fark nedir?', 'Nitel olasılık ve etkiyi derecelerle öncelikler, nicel risklerin sayısal etkisini hesaplar', ['İkisi aynıdır', 'Nitel yalnızca maliyeti, nicel yalnızca süreyi ele alır', 'Nicel analiz yalnızca uzman görüşüne, nitel analiz yalnızca simülasyon verisine dayanır'], 'Nitel analiz hızlıdır ve riskleri sıralar; nicel analiz (EMV, Monte Carlo) riskin proje süresi ve maliyetine olan etkisini sayılaştırır.'),
  ('Paydaş katılım değerlendirme matrisi hangi sorunu ortaya çıkarır?', 'Mevcut katılım düzeyi ile istenen düzey arasındaki farkı', ['Çalışanın maaşını', 'Proje takvimini', 'Kritik yol üzerindeki bolluk süresini ve her paydaşın bütçesini'], 'Matris, paydaşların bilinçsiz, direnen, tarafsız, destekleyen ya da liderlik eden olarak mevcut ve istenen durumunu karşılaştırır.'),
  ('\'Ceza şartı\' (liquidated damages) bir inşaat sözleşmesinde neyi ifade eder?', 'Gecikme gibi ihlallerde önceden belirlenen tazminatı', ['Yüklenicinin bonusunu', 'Ödeme erteleme hakkını', 'İşin kalitesini garanti etmek için yüklenicinin bir kere ödeyeceği teminat tutarını'], 'Gecikme günü başına önceden kararlaştırılan bedel, zarar kanıtlamadan alıcı lehine uygulanır.'),
  ('Satın alma sürecinde \'teklif talebi\' (RFP) ile \'fiyat talebi\' (RFQ) arasındaki fark nedir?', 'RFP çözüm ve yaklaşım önerisi ister, RFQ belirli bir ürün için fiyat ister', ['İkisi aynıdır', 'RFQ çözüm önerisi ister', 'RFP yalnızca fiyatın pazarlığı için kullanılır ve teknik içerik içermez'], 'RFQ tanımlı, standart ürünlerde fiyat toplar; RFP karmaşık işlerde teknik çözüm ve yöntem karşılaştırmasına dayanır.'),
  ('Üç noktalı tahminde PERT ağırlıklı ortalama yerine üçgen dağılım kullanılırsa beklenen süre nasıl hesaplanır?', '(a + m + b)/3', ['(a + 4m + b)/6', '(b − a)/6', 'a·m·b / 3 şeklinde üç değerin çarpımıyla'], 'Üçgen dağılım ortalaması üç tahminin eşit ağırlıklı ortalamasıdır; PERT ise en olası değere dört kat ağırlık verir.'),
  ('\'Control\' aşamasında iyileşmenin kalıcı olması için hangi araç kullanılır?', 'Kontrol grafiği ve standartlaştırılmış kontrol planı', ['Beyin fırtınası', 'Pareto analizi', 'Süreç sahibini ve ekibi değiştirip yeni projeye geçerek önceki çalışmayı izlememek'], 'Kontrol aşaması, kazanımı korumak için istatistiksel süreç kontrolü, standart iş talimatı ve yanıt planı kurar.'),
  ('Altı Sigma projelerinde \'hipotez testi\' (analyze aşaması) hangi amaçla kullanılır?', 'Bir nedenin sonuç üzerinde gerçek etkisi olup olmadığını istatistikle sınamak', ['Rastgele fikir üretmek', 'Maliyeti dağıtmak', 'Ekip üyelerinin fikir ayrılıklarını oylayarak bir sonuca bağlamak'], 'Analiz aşaması tahmin edilen kök nedenleri veriyle doğrular; böylece çözüm yanlış nedene yönlendirilmez.'),
  ('Deming\'in \'sürekli iyileştirme\' anlayışında yöneticilerin sorumluluğu hakkında temel görüşü nedir?', 'Kalite sorunlarının büyük bölümü sistemden doğduğundan sorumluluk yönetimdedir', ['Sorun çalışanların hatasıdır', 'Kalite yalnızca denetimle sağlanır', 'Kalite yalnızca ödüllendirme ile sağlanır'], 'Deming, değişkenliğin büyük kısmının ortak nedenlerden (sistem) geldiğini ve bunun yönetimce çözülebileceğini savundu.'),
  ('Japonya\'da 1951\'de kurulan ve Deming\'in adını taşıyan kalite ödülü hangi kuruluşça verilir?', 'JUSE', ['Toyota', 'Sony', 'MITI yani Japonya Dış Ticaret ve Sanayi Bakanlığı doğrudan olarak'], 'Deming Ödülü, JUSE tarafından Deming\'e ve onun öğretilerine minnet olarak 1951\'de kuruldu.'),
  ('Kaoru Ishikawa\'nın Japonya\'da yaygınlaştırdığı \'kalite çemberleri\' nedir?', 'Çalışanların küçük gruplarla iş sorunlarını çözdüğü gönüllü ekipler', ['Kalite denetçilerinin tek başına çalışması', 'Müşteri anketleri', 'Üst yönetimin saatlik toplantıları ve yıllık yönetim değerlendirme sunumu'], 'Kalite çemberleri, sahadaki çalışanların işleriyle ilgili sorunları kalite araçlarıyla kendi çözdüğü katılımcı yaklaşımdır.'),
  ('Yalın kalite çalışmalarında kullanılan, Toyota kökenli A3 raporu nedir?', 'Sorun, analiz ve çözüm planını tek sayfada özetleyen yöntem', ['A3 boyutlu çizim', 'Yalnızca bütçe raporu', 'Resmî yazışmaların imzalanıp kasada saklanması için kullanılan özel kâğıt boyutu'], 'A3, PDCA mantığıyla problem tanımı, kök neden ve karşı önlemleri tek sayfada görsel olarak paylaşan iletişim aracıdır.'),
  ('Kalite iyileştirmede \'karşılaştırmalı ölçüm\' (benchmarking) ne demektir?', 'Kendi performansını sektörün en iyi uygulamalarıyla karşılaştırıp öğrenmek', ['Rakibin ürününü kopyalamak', 'Kendi ürünleri arasında yarış yapmak', 'Üretim hattında bölümleri maliyete göre sıralayıp en düşük puanlıyı yeniden yapılandırmak'], 'Benchmarking, en iyi uygulamalardan öğrenerek boşluğu kapatmayı amaçlar; yalnızca rakip bile olması gerekmez.'),
  ('Hata ağacı analizinde \'asgari kesim kümesi\' (minimal cut set) neyi gösterir?', 'Üst olaya yol açan en küçük temel olay kombinasyonunu', ['Ağacın en uzun dalını', 'Olayların maliyetini', 'Tüm temel olayların aynı anda gerçekleşmesi gereken tek büyük birleşimi'], 'Asgari kesim kümesi, üst olayı oluşturmak için birlikte gerçekleşmesi gereken en az sayıdaki temel olay setidir.'),
  ('Süreç haritalamada \'yüzme şeridi\' (swimlane) diyagramının üstünlüğü nedir?', 'Hangi adımın hangi rol ya da bölüme ait olduğunu gösterir', ['Maliyeti hesaplar', 'Yalnızca tek kişi için çalışır', 'Yalnızca makine adımlarını gösterir ve insan işlerini kapsam dışı bırakır'], 'Swimlane akış şemasında her şeride bir rol/bölüm atanır; devir noktaları ve sorumluluk karışıklıkları görünür olur.'),
  ('PMBOK\'ta \'proje\' ile \'operasyon\' arasındaki temel fark nedir?', 'Proje geçici ve benzersiz çıktılı, operasyon süregelen ve tekrarlıdır', ['İkisi aynıdır', 'Operasyon geçicidir', 'Proje süregelen, operasyon bitiş tarihi olan ve tek seferlik girişimdir'], 'Proje belirli başlangıç ve bitişi olan benzersiz bir çabadır; operasyon ise sürekli tekrarlayan işleri yürütür.'),
  ('\'Program\' ile \'proje\' arasındaki ilişki nasıldır?', 'Program, birlikte yönetilen birbiriyle ilişkili projeler topluluğudur', ['Program tek bir görevdir', 'Program projeden küçüktür', 'Program, bir projenin yalnızca bütçe belgesine verilen addır ve kapsam içermez'], 'Program, tek tek yönetilseler elde edilemeyecek faydaları sağlamak için birlikte yönetilen proje gruplarıdır.'),
  ('Proje yöneticisinin yetkisi \'matris organizasyonda\' hangi özelliğiyle sınırlıdır?', 'Kaynakların işlevsel yöneticilere de bağlı olması', ['Hiç yetkisi olmaması', 'Yalnızca bütçeyi yönetmesi', 'Tüm ekibin doğrudan ona bağlı çalışması ve işlevsel müdür onayının hiç gerekmemesi'], 'Matris yapıda ekip üyeleri hem işlevsel müdüre hem proje yöneticisine bağlı olduğundan kaynak çatışmaları ortaya çıkabilir.'),
  ('Proje başlangıcında yazılan \'varsayımlar günlüğü\' neden önemlidir?', 'Planın dayandığı ama henüz doğrulanmamış kabulleri izleyip riski görünür kılar', ['Çalışanların maaşını yazar', 'Müşteriye gösterilmez', 'Yalnızca teslim edilen çıktıların listesini içerir ve değişiklik gerektirmez'], 'Varsayımlar yanlış çıkarsa plan çökebilir; günlük, bu kabullerin sorumlusu ve doğrulama zamanı ile birlikte takibini sağlar.'),
  ('Kapsam tanım belgesine neden \'kapsam dışı\' maddeleri de yazılır?', 'Beklenti farklarını ve sonradan çıkacak anlaşmazlıkları önlemek için', ['Belgeyi uzatmak için', 'Müşteriyi caydırmak için', 'Ekibin görev sınırlarının fazla genişlemesi için'], 'Neyin yapılmayacağını açıkça yazmak, paydaşların varsaydıkları ama planda olmayan işleri istemesini önler.'),
  ('Kazanılmış değer yönetiminde \'planlanan değer\' (PV) neyi gösterir?', 'Belirli bir tarihe kadar planlanan işin bütçelenmiş değerini', ['Gerçekleşen harcamayı', 'Tamamlanan işin değerini', 'Projenin kapanışında ödenecek toplam bonus ve ödül tutarını'], 'PV, o zamana kadar bitirilmesi planlanan işe verilmiş bütçedir; EV ile karşılaştırarak program sapması bulunur.'),
  ('PV = 200, EV = 150, AC = 180 ise program sapması (SV) kaçtır?', '−50', ['+50', '−30', '+30'], 'SV = EV − PV = 150 − 200 = −50\'dir; negatif sapma geride kalındığını gösterir.'),
  ('Proje kapanışında \'sözleşme kapanışı\' neden gerekir?', 'Tarafların yükümlülüklerini tamamladığını ve talep bırakmadığını belgelemek için', ['Maliyeti artırmak için', 'Ekibi dağıtmak için', 'Ürünün teknik tasarım değişikliklerinin iptal edilmesi için'], 'Resmî kapanış ödemeleri, garanti ve açık kalemleri netleştirir; sonradan çıkabilecek uyuşmazlıkları azaltır.'),
  ('Proje sonrası değerlendirmede (post-mortem) amaç nedir?', 'Nelerin iyi gittiğini ve iyileştirilmesi gerekenleri belirlemek', ['Sorumlu aramak', 'Raporu kapatmak', 'Bütün ekip üyelerini ilgili işlerinden uzaklaştırıp yeniden atamak'], 'Sonuç değerlendirmesi, suçlama yerine öğrenmeye odaklanır; çıkan dersler kurumsal bilgiye eklenir.'),
  ('Türkiye\'de ilk yardımcı sayısı belirlenirken çok tehlikeli sınıftaki işyerlerinde kaç çalışana en az bir ilk yardımcı bulundurulur?', 'On', ['Yirmi', 'Elli', 'Yüz'], 'Yönetmeliğe göre ilk yardımcı oranı çok tehlikeli işyerlerinde her 10, tehlikeli işyerlerinde her 15, az tehlikeli işyerlerinde her 20 çalışan için en az birdir.'),
  ('Türkiye\'de işverenin risk değerlendirmesini kimlerin katılımıyla yaptırması beklenir?', 'İşveren, iş güvenliği uzmanı, işyeri hekimi ve çalışan temsilcisi gibi ekip', ['Yalnızca müşteri', 'Yalnızca sigorta şirketi', 'Yalnızca işveren tek başına ve yalnızca kendi bilgisiyle'], 'Risk değerlendirmesi, işveren veya vekili, uzman, hekim, çalışan temsilcileri ve destek elemanlarını içeren bir ekiple yürütülür.'),
  ('Türkiye\'de işyeri hekimi ve iş güvenliği uzmanı hizmetlerinin amacı en iyi nasıl tarif edilir?', 'İşverene danışmanlık yaparak risklerin önlenmesine yardımcı olmak', ['Çalışanları cezalandırmak', 'Üretim planı yapmak', 'İşverenin yerine tüm sorumluluğu devralmak ve hukuki sorumluluğu üstlenmek'], 'Uzman ve hekim danışmanlık, rehberlik ve izleme yapar; asıl yükümlülük kanunen işverende kalır.'),
  ('Bir tehlikeli madde için \'zaman ağırlıklı ortalama\' (TWA) maruziyet sınırı neyi ifade eder?', '8 saatlik vardiya boyunca ortalama izin verilen derişimi', ['Anlık olarak hiçbir zaman aşılmaması gereken derişimi', 'Günlük üretim miktarını', 'Bir saatlik kısa süreli en yüksek derişimi'], 'TWA, işçinin tipik 8 saatlik çalışma günündeki ortalama maruziyet sınırıdır; kısa süreli üst sınır STEL ile ayrıca belirtilir.'),
  ('Karbon monoksit gazı neden \'sessiz katil\' olarak anılır?', 'Renksiz ve kokusuz olup kanda hemoglobine bağlanarak oksijen taşınmasını engeller', ['Çok kokulu olduğu için', 'Hızlı yandığı için', 'Çok ağır olduğu için dibe çöker ve görünür sis oluşturur'], 'CO duyularla fark edilmez; hemoglobine oksijenden çok daha güçlü bağlanarak kişide baş ağrısı, bilinç kaybı ve ölüme yol açar.'),
  ('Azot (nitrojen) kaçağı olan kapalı bir depoda neden boğulma olabilir?', 'Azot oksijeni yerinden iterek oksijen düzeyini düşürür', ['Azot zehirlidir', 'Azot sıcak yakar', 'Azot sıvı hâlde bulunduğu için akciğerleri donarak çalışmaz hâle getirir'], 'Azot zehirli değildir ama havadaki oksijen oranını düşürür; algılanmadığından kişi uyarı hissetmeden bilincini kaybeder.'),
  ('Bir merdiven dayama kuralı 4:1 ise 6 m yüksekliğe dayanacak merdivenin tabanı duvardan yaklaşık kaç metre uzağa konur?', '1,5', ['4', '0,6', '2,4'], '4:1 kuralında yükseklik/taban uzaklığı = 4\'tür; 6/4 = 1,5 m taban uzaklığı gerekir.'),
  ('Sıcak iş (kaynak, kesme) sonrasında alanda bir süre yangın gözcüsü bekletilmesinin nedeni nedir?', 'Gizli kalan kıvılcım ve ısının sonradan yangın çıkarmasını izlemek', ['Gözcünün maaşını artırmak', 'Kaynakçıyı denetlemek', 'İşin süresini ve ek ücretini pazarlık konusu yapmak'], 'Kıvılcımlar ve sıcak yüzeyler saatler sonra bile yanıcı malzemeyi tutuşturabilir; bu yüzden iş sonrası izleme süresi uygulanır.'),
  ('Çamaşır suyu ile amonyak içerikli bir temizleyicinin karıştırılması neden tehlikelidir?', 'Zehirli kloramin gazı oluşur', ['Temizlik gücü artar', 'Köpürmez', 'Karışım anında donarak kabı çatlatır ve cildi yakar'], 'Hipoklorit ile amonyak tepkimesi kloramin buharları üretir; solunum yollarını ciddi biçimde tahriş eder.'),
  ('Laboratuvarda çeker ocak (fume hood) kullanmanın amacı nedir?', 'Zararlı buhar ve gazları çalışanın solunum bölgesinden uzaklaştırmak', ['Odayı aydınlatmak', 'Cihazları soğutmak', 'Çalışma yüzeyini sıcak tutmak ve cam malzemeyi kurutmak'], 'Çeker ocak, ön açıklıktan hava çekerek tehlikeli buharları atmosfere ve filtreye yönlendirir; yerel egzoz örneğidir.'),
  ('Elektrikli el aletlerinde \'çift yalıtım\' simgesi (iç içe iki kare) neyi belirtir?', 'Alet gövdesinin ek topraklama gerektirmeyecek biçimde iki kat yalıtıldığını', ['Aletin su geçirmez olduğunu', 'Aletin çift hızlı olduğunu', 'Aletin iki farklı gerilimde çalışabildiğini'], 'Çift yalıtımlı (Sınıf II) aletlerde bir yalıtım arızalansa da ikincisi koruma sağlar; toprak iletkeni gerekmez.'),
  ('Islak ve iletken ortamlarda (kazan içi gibi) elektrikli el lambası için hangi gerilim sınıfı tercih edilir?', 'Çok düşük (örneğin 12 V ya da 24 V) güvenlik gerilimi', ['230 V', '400 V', 'Kablonun uzun olması gerekçesiyle 230 V ile kaçak akım rölesiz'], 'Çok düşük güvenlik gerilimi, yalıtım arızasında bile çarpılma akımını tehlikeli düzeyin altında tutar.'),
  ('Yıldırım düşmesine karşı binalarda paratoner sisteminin işlevi nedir?', 'Yıldırım akımını güvenli biçimde toprağa ileterek yapıyı korumak', ['Yıldırımı çekip tüm bölgeye yaymak', 'Yıldırımı engellemek', 'Yıldırımın düşüşünü önceden haber vermek ve alarm üretmek'], 'Paratoner yakalama ucu, iniş iletkenleri ve topraklama ile akımı yapıya zarar vermeden toprağa taşır.'),
  ('Eşdeğer ses düzeyi 91 dB(A) ise ve 85 dB(A) için 8 saat, 3 dB değişim kuralı geçerliyse günlük izin verilen süre kaç saattir?', '2', ['4', '1', '6'], 'Her 3 dB artışta izin verilen süre yarıya iner: 85 → 8 saat, 88 → 4 saat, 91 → 2 saattir.'),
  ('Aynı kurala göre 94 dB(A) düzeyinde izin verilen günlük süre kaç saattir?', '1', ['0,5', '2', '3'], '85 için 8 saat; 94 dB, 85\'in 9 dB üstüdür (üç adım); 8/2³ = 1 saattir.'),
  ('Aynı sürede iki özdeş makine çalışıyor ve her biri tek başına 80 dB üretiyor. Birlikte toplam ses düzeyi yaklaşık kaç dB olur?', '83', ['160', '85', '90'], 'Özdeş iki kaynağın toplamı L + 10·log₁₀(2) ≈ L + 3 dB\'dir. Desibeller doğrudan toplanmaz.'),
  ('Gürültü kontrolünde kaynağa yönelik önlemlerden biri hangisidir?', 'Daha sessiz makine seçmek veya titreşimi sönümlemek', ['Kulak tıkacı dağıtmak', 'Çalışma süresini sabit bırakmak', 'Çalışanlara düzenli işitme testi yapıp sonuçları yalnızca arşivde saklamak'], 'Kaynakta azaltma (sessiz ekipman, sönümleme, bakım) kontrol hiyerarşisine uygun etkili yöntemdir; tıkaç ise KKD\'dir.'),
  ('Yangın yükü (kalori yükü) neyi ifade eder?', 'Bir mekândaki yanıcı maddelerin yanınca açığa çıkaracağı toplam ısı enerjisini', ['Yangında yanan alanın büyüklüğünü', 'Yangının süresini', 'Yangın söndürücü sayısı ile binanın toplam kat sayısının çarpımını'], 'Yangın yükü birim alana düşen potansiyel ısı miktarıdır ve yangına dayanıklılık süresi gereksinimini etkiler.'),
  ('Yangın kapılarının kendiliğinden kapanır olması neden önemlidir?', 'Dumanın ve alevin yayılmasını sınırlayıp tahliye yollarını korur', ['Daha az gürültü yapar', 'Kapı kolu aşınmaz', 'Kapıyı açık tutma ihtiyacını ortadan kaldırıp havalandırmayı keser'], 'Kapalı yangın kapısı ateş ve duman bölmelemesi sağlar; açık bırakılırsa bölme işlevini yitirir.'),
  ('Yağmurlama (sprinkler) sisteminde kapalı tip sprinkler başlığı nasıl devreye girer?', 'Isıya duyarlı cam ampul ya da eriyen bağ ısınınca açılır', ['Duman görünce açılır', 'Elle açılır', 'Yangın alarmı çaldığında merkezden gönderilen elektrik sinyaliyle'], 'Isıya duyarlı ampul belirli sıcaklıkta patlar ve yalnız o bölgedeki başlık su püskürtür.'),
  ('Yangın tahliye planında \'toplanma yeri\' neden belirlenir?', 'Herkesin tahliye sonrası sayılıp kayıp kişilerin saptanabilmesi için', ['İnsanları kalabalık etmek için', 'Sosyal etkinlik için', 'Binayı boşaltan kişilerin otopark ile bina girişini kullanarak tekrar içeri girmesini sağlamak için'], 'Toplanma yerinde yoklama yapılır; içeride kalan kişi varsa kurtarma ekibine bildirilir.'),
  ('\'Güvensiz davranış\' ile \'güvensiz durum\' arasındaki fark nedir?', 'Davranış insanın eylemi, durum ise ortam ya da ekipmandaki eksikliktir', ['İkisi aynıdır', 'Durum yalnızca insanın ruh hâlidir', 'Davranış ekipmanın arızasıdır ve durum yalnızca resmî evrak eksikliğidir'], 'Korkuluksuz iskele güvensiz durumdur; kemerini takmadan çalışan işçinin hareketi güvensiz davranıştır.'),
  ('Davranış temelli güvenlik programlarında gözlem ve geri bildirimin amacı nedir?', 'Güvenli davranışı pekiştirip riskli davranışı azaltmak', ['Çalışanı cezalandırmak', 'Üretim sürelerini ölçmek', 'Davranışsal bulguları yalnızca yönetim raporuna işleyip saha ekibiyle hiç paylaşmamak'], 'Düzenli, suçlayıcı olmayan gözlem ve olumlu geri bildirim güvenli alışkanlıkları kalıcı hâle getirir.'),
  ('CUSUM kontrol grafiğinin klasik Shewhart grafiğine göre başlıca üstünlüğü nedir?', 'Ortalamadaki küçük ama kalıcı kaymaları daha hızlı yakalaması', ['Kaymayı hiç göstermemesi', 'Yalnızca büyük sapmaları görmesi', 'Her noktayı bağımsız değerlendirip geçmiş veriyi kullanmaması'], 'CUSUM geçmiş sapmaları biriktirerek küçük ve sürekli kaymaları erken saptar; Shewhart grafiği büyük sıçramalara duyarlıdır.'),
  ('Aşırı tepki (overadjustment) hatası, Deming\'in huni deneyine göre ne demektir?', 'Kontrol altındaki bir süreci her sapmada ayarlamanın değişkenliği artırması', ['Sürece hiç dokunmamak', 'Ölçüm hatası yapmak', 'Üretim hızını düşürüp yalnızca ayar sürelerini uzatmak'], 'Rastgele (ortak neden) sapmaya ayarla tepki vermek varyansı artırır; ayar yalnızca özel neden işareti varsa yapılmalıdır.'),
  ('Sıfır kabul (c = 0) planlarının tercih edilmesinin gerekçesi nedir?', 'Örnekte tek bir hata bile partiyi reddettirir ve kaliteye duyarlılığı artırır', ['Daha az kontrol yapılır', 'Hatalı ürünü kabul eder', 'Örnek büyüklüğü artırılarak kalite hedefinin otomatik olarak sıfırlanması'], 'c = 0 planları örnekte hiç kusur istemez; güvenlik açısından kritik kusurlar için uygundur.'),
  ('Kabul örneklemesinin \'tamamen muayene\' ile karşılaştırılmasında en önemli dezavantajı nedir?', 'İyi partinin yanlışlıkla reddi ve kötü partinin yanlışlıkla kabul riski', ['Maliyetin yüksek olması', 'Süresinin çok uzun olması', 'Tüm ürünlerin tek tek kontrol edilmesi gerektiği'], 'Örnekleme zaman ve maliyet kazandırır ama her zaman α ve β risklerini barındırır.'),
  ('Bir mikrometre 0,01 mm çözünürlüğe sahipse kaba bir kural olarak ölçülen özelliğin toleransı en az ne kadar olmalıdır?', 'Yaklaşık 0,1 mm', ['0,01 mm', '0,001 mm', '0,011 mm, çünkü çözünürlük ile aynı sayısal basamakta tutulur'], '\'On a bir\' ya da \'on kuralı\' ölçü aleti çözünürlüğünün toleransın onda biri kadar ya da daha ince olmasını önerir.'),
  ('ISO 9001 standardında \'sürekli iyileştirme\' hangi döngüyle ilişkilendirilir?', 'PDCA', ['DMADV', 'SMART', 'ABC analizi ve yalnızca maliyet iyileştirme döngüsü'], 'Standardın süreç yaklaşımı PDCA ile risk temelli düşünmeyi birleştirir.'),
  ('ISO 14001 tarafından belirlenen \'çevre boyutu\' (environmental aspect) neyi ifade eder?', 'Kuruluş faaliyetlerinin çevreyle etkileşime giren unsurunu', ['Çevredeki tüm ağaçları', 'Bina büyüklüğünü', 'Yalnızca atık suyun renginin ölçülmesini ve rapor edilmesini'], 'Çevre boyutu (emisyon, atık, su kullanımı gibi) çevreye etki yaratabilen faaliyet, ürün veya hizmet unsurudur.'),
  ('Bir fabrika enerji performansını sistemli biçimde izleyip iyileştirmek için sertifikalı bir yönetim sistemi kuracaktır. Hangi standardı seçmelidir?', 'ISO 50001', ['ISO 14001, yani çevre yönetim sistemi', 'ISO 45001', 'ISO 22000'], 'ISO 50001 kuruluşların enerji performansını sistemli biçimde izleyip iyileştirmesini sağlar.'),
  ('Bir ürünün \'garanti süresi\' ile \'ortalama ömrü\' arasındaki ilişki için doğru ifade hangisidir?', 'Garanti süresi ortalama ömürden çok daha kısa olabilir; ikisi aynı değildir', ['Her zaman eşittir', 'Garanti süresi hep ortalama ömürden uzundur', 'Garanti süresi ortalama ömrün her koşulda tam yarısına eşit olarak belirlenir'], 'Garanti süresi, erken arıza oranının ekonomik olarak karşılanabilir olduğu süredir; ortalama ömür bundan çok uzun olabilir.'),
  ('İnsan hatası sınıflamasında \'slip\' (sürçme) ile \'mistake\' (yanlış karar) arasındaki fark nedir?', 'Sürçme doğru niyetin hatalı uygulanmasıdır, yanlış karar ise niyetin kendisinin hatalı olmasıdır', ['İkisi aynıdır', 'Sürçme kasıtlıdır', 'Yanlış karar yalnızca fiziksel bir tökezlemedir ve niyetle bağlantısı yoktur'], 'Reason\'a göre sürçme ve unutma (lapse) yürütme hatasıdır; plan hatalı olduğunda \'mistake\', kurallara bilerek uymamak ise \'violation\' olur.'),
  ('Yorgunluk, iş yükü ve tasarım zayıflıkları gibi \'hata üreten koşullar\' için hangi yaklaşım doğrudur?', 'Kişiyi suçlamak yerine koşulları iyileştirmek', ['Kişileri işten çıkarmak', 'Koşulları görmezden gelmek', 'Hataya düşen kişilere ek prosedür yığınları ve tekrar eğitim yağdırmak'], 'İnsan faktörleri bakışında hata, koşulların ürünüdür; iş yükünü, arayüzü ve iletişimi düzeltmek tekrarı azaltır.'),
  ('Havacılıkta \'ekip kaynak yönetimi\' (CRM) eğitiminin amacı nedir?', 'İletişim, karar ve ekip çalışması becerileriyle insan hatasını azaltmak', ['Uçağı daha hızlı uçurmak', 'Yakıt tasarrufu sağlamak', 'Pilotların uçuş sırasında yalnızca otomatik pilota güvenmesini öğretmek'], 'CRM, kokpit ve kabin ekibinin birlikte çalışmasını, hiyerarşi bariyerlerini aşmayı ve hataları erken fark etmeyi hedefler.'),
  ('İnsan faktörlerinde \'durumsal farkındalık\' (situational awareness) neyi anlatır?', 'Çevrede olup bitenin algılanması, anlamlandırılması ve ilerisinin kestirilmesini', ['Kişinin boy uzunluğunu', 'Takımın sayısını', 'Kişinin yalnızca ekipman kullanım kılavuzunu ezbere bilmesini'], 'Durumsal farkındalık algı, anlama ve öngörü düzeylerinden oluşur; kaybedildiğinde karar hataları artar.'),
  ('Proses güvenliği ile iş güvenliği arasındaki temel fark nedir?', 'Proses güvenliği büyük felaket olaylarını, iş güvenliği bireysel yaralanmaları öne çıkarır', ['İkisi aynıdır', 'Proses güvenliği yalnızca ofislerdedir', 'İş güvenliği yalnızca kimyasal fabrikalar için geçerli ve büyük kaza riskine odaklıdır'], 'Proses güvenliği kimya ve petrol tesislerinde yangın, patlama, toksik salım gibi büyük kaza risklerini yönetir.'),
  ('Basınçlı kapların yangında patlamasıyla ilgili BLEVE olayı nedir?', 'Basınçlı kapta sıvının kaynayan buharının aniden genleşmesiyle oluşan patlama', ['Küçük bir elektrik kıvılcımı', 'Gaz sızıntısı sonrası zehirlenme', 'Katı yakıtın yavaş yanıp yangın söndürme sisteminde basınç düşürmesi'], 'BLEVE (kaynayan sıvı genleşen buhar patlaması), basınçlı kabın yangında zayıflayıp açılması sonucu aşırı ısınmış sıvının aniden buharlaşmasıdır.'),
  ('Proseste bir emniyet valfinin (basınç tahliye valfi) görevi nedir?', 'Basınç güvenli sınırı aşınca açılıp fazlalığı tahliye etmek', ['Akışı artırmak', 'Sıcaklığı ölçmek', 'Boru hattını sürekli açık tutup debiyi sabitleyerek basıncı artırmak'], 'Emniyet valfi, kabın kabul edilebilir basıncını aşmasını önleyen son güvence elemanıdır.'),
  ('Güvenlik enstrümanlı sistemlerde (SIS) \'bypass\' (köprüleme) neden kontrollü yapılır?', 'Kontrolsüz köprüleme korumayı devre dışı bırakıp felakete yol açabilir', ['Köprüleme pahalıdır', 'Köprüleme hiç gerekmez', 'Köprüleme daha yüksek verim sağlayıp ek incelemeyi gereksiz kılar'], 'Bakım için gerekli geçici köprülemeler izne bağlanır, süreleri ve telafi edici önlemleri kayıt altındadır.'),
  ('Basınçlı bir boru hattında bakım için \'çift bloke ve tahliye\' düzenlemesi ne sağlar?', 'İki vana arasındaki tahliye ile sızdırmayan güvenilir izolasyon', ['Debiyi artırır', 'Hattı süsler', 'Hattı sürekli basınç altında tutarak ölçümü kolaylaştırır'], 'İki kapalı vana arasındaki tahliye (bleed) vanası, bir vana sızdırsa da çalışma bölgesine basınç ulaşmasını önler.'),
  ('Kondansatör içeren elektrik donanımında bakım öncesi enerji kesilse de neden hâlâ risk vardır?', 'Kondansatörlerde depolanmış yük olabilir', ['Kablolar dikkat çekmez', 'Şalter her zaman bozuktur', 'Elektrik akımı kesinti sonrası da bir süre güç kaynağından geri akar'], 'Kondansatör şarjı güç kesildikten sonra da tehlikeli gerilimi tutabilir; boşaltma ve ölçümle doğrulama gerekir.'),
  ('Hidrolik makinede bakım sırasında yüklü pistonun düşmesine karşı hangi önlem alınır?', 'Mekanik destek ya da bloke pimi ile yükü tutmak', ['Hidrolik yağını koyulaştırmak', 'Çalışanı hızlandırmak', 'Yalnızca pompayı kapatıp piston konumunun kendiliğinden sabit kalacağına güvenmek'], 'Basınç düşünce yük yerçekimiyle inebilir; fiziksel destek pimi gibi mekanik bloklama zorunludur.'),
  ('Ramak kala bildirimlerinin yönetilmesinde en önemli unsur hangisidir?', 'Bildirenin cezalandırılmaması ve olayın hızlı incelenip geri bildirim verilmesi', ['Bildirimin gizli tutulması', 'Raporun ay sonunda yazılması', 'Bildirimlerin yalnızca sayı olarak toplanıp saha ekibine hiç dönüş yapılmaması'], 'Güven ve geri bildirim olmadan bildirim azalır; hızlı kapanış ve görünür düzeltme, kültürü besler.'),
  ('Olay soruşturmasında \'kanıt koruma\' neden ilk adımlardan biridir?', 'Kazanın gerçek koşullarını değiştirmeden kayıt altına almak için', ['Fotoğraf çekmek için', 'Çalışanı korkutmak için', 'Alanın hemen temizlenip üretime dönülmesini kolaylaştırmak için'], 'Parçalar, konumlar ve kayıtlar kaybolursa kök neden bulunamaz; yerinde fotoğraf, ölçü ve tanık ifadesi hemen alınır.'),
  ('Otomotivde APQP (ileri ürün kalite planlaması) neyi amaçlar?', 'Ürün geliştirme sürecinde kalite risklerini erken planlayıp yönetmeyi', ['Ürünün reklam bütçesini planlamayı', 'Bayi ağını kurmayı', 'Müşterinin fiyat pazarlığını aşamalara bölerek ödemeyi yönetmeyi'], 'APQP, tasarım ve proses geliştirme boyunca planlama, risk analizi ve doğrulama aşamalarını yapılandıran bir çerçevedir.'),
  ('PPAP (üretim parçası onay süreci) hangi amaçla kullanılır?', 'Tedarikçinin seri üretimde şartnameyi tutarlı karşılayabildiğini kanıtlamak', ['Parçanın pazarlama gücünü ölçmek', 'Parçanın fiyatını belirlemek', 'Tedarikçinin nakliye firmasını seçmek ve teslimat güzergâhını onaylamak'], 'PPAP, tedarikçinin ölçüm sonuçları, kontrol planı ve yeterlilik kanıtlarıyla seri üretime geçiş onayını almasıdır.'),
  ('Bir tedarikçi 200 000 parça teslim etti ve 30 hatalı parça çıktı. PPM değeri kaçtır?', '150', ['30', '0,15', '6667'], 'PPM = 30/200 000 × 10⁶ = 150\'dir.'),
  ('Pareto grafiğinde \'kümülatif yüzde çizgisi\' neyi gösterir?', 'Nedenler büyükten küçüğe eklendikçe toplam payın ne kadarının açıklandığını', ['Her nedenin maliyetini', 'Zamanla değişimi', 'Her nedenin ortalama onarım süresiyle toplam arıza süresini'], 'Kümülatif çizgi, ilk birkaç nedenin sorunların kaçta kaçını oluşturduğunu gösterir; öncelik belirlemeyi kolaylaştırır.'),
  ('Duyarlılık analizinde \'tornado diyagramı\' neyi gösterir?', 'Her belirsiz değişkenin sonuç üzerindeki etkisinin büyüklüğünü sıralı olarak', ['Rüzgâr hızını', 'Takım hızını', 'Ekip üyelerinin vardiya düzenini ve tatil günlerini'], 'Tornado diyagramı, hangi girdi belirsizliğinin çıktıyı en çok değiştirdiğini en üstte göstererek önceliği belirler.'),
  ('Risk yönetiminde \'risk iştahı\' (risk appetite) neyi anlatır?', 'Kuruluşun hedeflerine ulaşmak için kabul etmeye hazır olduğu risk düzeyini', ['Çalışanların yemek tercihlerini', 'Risklerin sayısını', 'Tüm risklerin en üst yönetimce bir kez onaylandıktan sonra sabitlenen toplam puanını'], 'Risk iştahı stratejik düzeyde belirlenir; proje riskleri bu eşiklere göre değerlendirilir.'),
  ('Proje yöneticisi \'şeffaf iletişim\' ilkesini uygularken kötü haberi nasıl ele almalıdır?', 'Erken, olgusal ve çözüm önerileriyle paydaşa iletmelidir', ['Gizlemelidir', 'Son güne bırakmalıdır', 'Yalnızca ekip içinde tutup müşteriye ancak teslimden sonra söylemelidir'], 'Kötü haber geciktikçe seçenekler azalır ve güven kaybolur; erken bildirim ortak çözüm şansı verir.'),
  ('Anlaşmazlık çözme yöntemlerinden \'iş birliği/problem çözme\' yaklaşımının özelliği nedir?', 'Tarafların çıkarlarını birlikte karşılayan kalıcı çözüm aranması', ['Birinin zorla kazanması', 'Sorunun görmezden gelinmesi', 'Her iki tarafın da ortada buluşmak için yarı yarıya taviz vermesi'], 'İş birliği, \'kazan-kazan\' çözümü hedefler; uzlaşma ise taraflar arası taviz içerir ve genelde daha düşük memnuniyet verir.'),
  ('Ürün sahibinin \'kabul ölçütü\' (acceptance criteria) yazmasının amacı nedir?', 'Bir hikâyenin kabul edilebilir sayılması için doğrulanabilir koşulları belirlemek', ['Takım üyelerinin maaşını artırmak', 'Sprint süresini uzatmak', 'Hikâyenin hangi geliştirici tarafından yapılacağını önceden bildirmek'], 'Kabul ölçütleri, geliştirici ve ürün sahibi arasında ortak anlayış kurar; test ve onay kararı bu ölçütlere dayanır.'),
  ('Çevik yöntemlerde \'tempo sürdürülebilirliği\' ilkesi ne demektir?', 'Ekibin uzun süre sabit ve makul hızda çalışabilmesi', ['Sürekli fazla mesai', 'Hızın sürekli artırılması', 'Ekibin sprintin son günlerinde aşırı yoğunlaşıp ilk günlerde dinlenmesi'], 'Manifesto ilkesi sürdürülebilir hızı savunur; sürekli aşırı çalışma kaliteyi ve kişileri tüketir.'),
  ('Prototipleme modelinin başlıca yararı nedir?', 'Kullanıcıya erken bir örnek göstererek gereksinim yanlış anlamalarını azaltmak', ['Kodlamayı atlamak', 'Testi kaldırmak', 'Gereksinim belgesini tamamen ortadan kaldırıp müşteriyle yalnızca sözlü anlaşmak'], 'Prototip erken geri bildirim sağlar; gereksinimlerin netleşmesine ve geç ve pahalı değişikliklerin önlenmesine yardım eder.'),
  ('Eşzamanlı mühendislik (concurrent engineering) neyi önerir?', 'Tasarım, üretim ve kalite ekiplerinin ürün geliştirmeyi paralel ve iş birliğiyle yürütmesini', ['Aşamaların sırayla ve izole yapılmasını', 'Hiç ekip kurmamayı', 'Önce tasarımı bitirip ancak sonra üretim ekibine sormayı'], 'Eşzamanlı mühendislik, üretilebilirlik ve test gibi sorunları erken görüp süreyi kısaltmayı ve yeniden tasarımı azaltmayı hedefler.'),
  ('\'Konik belirsizlik\' (cone of uncertainty) kavramı neyi anlatır?', 'Projenin başında tahminlerin çok belirsiz olduğunu, ilerledikçe daraldığını', ['Tahminlerin hep aynı kaldığını', 'Belirsizliğin zamanla arttığını', 'Belirsizliğin yalnızca proje sonunda ortaya çıktığını ve başlangıçta hiç görülmediğini'], 'Başlangıçta bilinmeyenler fazladır; öğrenildikçe tahmin aralığı daralır. Bu yüzden erken tahminler aralık olarak verilmelidir.'),
  ('Bir etkinlik için ES = 3, EF = 9, LS = 5, LF = 11 verilmiştir. Etkinliğin süresi ve toplam bolluğu nedir?', 'Süre 6 gün, bolluk 2 gün', ['Süre 6 gün, bolluk 0 gün', 'Süre 8 gün, bolluk 2 gün', 'Süre 2 gün, bolluk 6 gün'], 'Süre = EF − ES = 6; bolluk = LS − ES = 5 − 3 = 2 gündür (LF − EF = 2 ile tutarlı).'),
  ('Projede iki ardışık etkinliğin 3 günlük bolluğu aynı yoldan paylaşılıyorsa birinci etkinlik 2 gün gecikirse ikincinin bolluğu ne olur?', '1 güne düşer', ['3 gün kalır', '5 güne çıkar', 'Sıfırlanır ve kritik hâle gelir'], 'Ortak bolluk paylaşıldığından birinin kullandığı kısım diğerinden düşer: 3 − 2 = 1 gün kalır.'),
  ('Bir etkinlik 12 günden 9 güne düşürülerek maliyeti 4800 TL\'den 6000 TL\'ye çıkıyor. Maliyet eğimi kaç TL/gündür?', '400', ['1200', '300', '1600'], 'Eğim = (6000 − 4800)/(12 − 9) = 1200/3 = 400 TL/gündür.'),
  ('PV = 50, EV = 50, AC = 40 ise proje nasıl tanımlanır?', 'Programa uygun ve bütçenin altında', ['Programa uygun ama bütçeyi aşmış', 'Programın gerisinde ve bütçeyi aşmış', 'Programın ilerisinde ve bütçeyi aşmış'], 'SPI = 1,0 (programda), CPI = 50/40 = 1,25 (bütçenin altında).'),
  ('PV = 120, EV = 100, AC = 90 ise SPI ve CPI sırasıyla yaklaşık nedir?', '0,83 ve 1,11', ['1,20 ve 0,90', '0,83 ve 0,90', '1,20 ve 1,11'], 'SPI = 100/120 ≈ 0,83; CPI = 100/90 ≈ 1,11. Program geride, maliyet planın altındadır.'),
  ('Poka-yoke\'nin \'kontak yöntemi\' (contact method) neyi inceler?', 'Parçanın şekil, boyut veya renk gibi fiziksel özelliklerini sensör ya da kılavuzla kontrol eder', ['Çalışanı denetler', 'Satış sayısını sayar', 'Üretilen parçaların yalnızca sayısını raporlayıp özelliklerini incelemez'], 'Kontak yöntemi, yanlış yönde ya da yanlış boyutta parçanın sensör veya kılavuz tarafından fiziken reddedilmesini sağlar.'),
  ('İdeal çevrim süresi 30 sn olan bir makine 420 dk çalışmada 700 parça üretiyor. Performans oranı kaçtır?', '%83', ['%120', '%50', '%70'], 'İdeal üretim = 420 × 60/30 = 840 parça. Performans = 700/840 ≈ 0,83\'tür.'),
  ('1000 parça üreten bir makinede 50 parça hatalıdır. Kalite oranı kaçtır?', '%95', ['%5', '%50', '%99'], 'Kalite oranı = iyi parça/toplam = 950/1000 = %95\'tir.'),
  ('ISO 45001\'de \'işçilerin katılımı ve danışılması\' ne anlama gelir?', 'Çalışanların iş sağlığı ve güvenliği kararlarına dahil edilmesi', ['Çalışanların yalnızca imza atması', 'Çalışanların iş güvenliği uzmanını seçmesi', 'Yalnızca yönetimin duyurularını izleyip geri bildirim vermemesi'], 'Standart, çalışanların tehlike belirleme, risk değerlendirme ve olay soruşturmalarına aktif katılımını şart koşar.'),
  ('Çalışma masasının yüksekliği ayarlanabilir olmalıdır çünkü:', 'Kullanıcıların antropometrik farkları farklı yükseklik gerektirir', ['Masa daha pahalı görünür', 'Her çalışanın boyu aynıdır', 'Masa yüksekliği hiçbir zaman çalışanın omuz ve dirsek postürünü etkilemez'], 'Ayarlanabilirlik, antropometrik çeşitliliğe uyum sağlar; yanlış masa yüksekliği omuz ve bilek zorlanmasına yol açar.'),
  ('Çalışma alanında \'ulaşma bölgeleri\' tasarımında sık kullanılan öğeler nereye konmalıdır?', 'Rahat erişilen normal ulaşma alanına', ['En uzak köşeye', 'Başın arkasına', 'Yerden bel altına, eğilmeyi artıracak şekilde sık kullanılan öğeleri koyarak'], 'Sık kullanılanlar dirsek ekseninde kolay ulaşım bölgesine, seyrek kullanılanlar daha uzağa yerleştirilir.'),
  ('Uzatma kablosunun makara halinde sarılı kullanılması neden tehlikelidir?', 'Sarım içinde ısı birikip aşırı ısınma ve yangın riski yaratır', ['Kablo uzar', 'Kablo soğur', 'Kablo gerilimi artırarak makaranın dönüş yönünü değiştirir'], 'Sarılı kablodan geçen akım ısıyı dışarı atamaz; yalıtım erir ve yangın çıkabilir. Kablo tamamen açılmalıdır.'),
  ('Acil bir değişiklik talebinde bile kayıt tutulmasının gerekçesi nedir?', 'Sonradan izlenebilirlik ve etki değerlendirmesi için', ['Gereksiz kâğıt işi ve zaman kaybı yaratmak', 'Maliyet artırmak', 'Talebi geciktirip karar vermeyi sonraya bırakmak'], 'Acil durumda süreç hızlandırılsa da yapılan değişiklik kayıt altına alınmalı; aksi hâlde tasarım ve saha durumu uyuşmaz.'),
  ('Histogramda çift tepeli (iki modlu) dağılım ne olasılığı düşündürür?', 'İki farklı kaynağın (makine, vardiya) verisinin karışmış olabileceğini', ['Sürecin mükemmel olduğunu', 'Ölçüm hatası olmadığını', 'Verilerin yalnızca normal dağılıma tam uyduğunu'], 'Çift tepe genellikle iki ayrı sürecin birlikte ölçüldüğünü gösterir; veriler tabakalanıp ayrı incelenmelidir.'),
  ('Yedek parça stoğunda \'kritik yedek\' kavramı neyi ifade eder?', 'Arızası üretimi uzun süre durdurabilecek ve temini zor parçaları', ['Her türlü cıvata', 'Ucuz parçaları', 'Yalnızca sık değiştirilen sarf malzemelerinin tamamını'], 'Kritik yedekler, uzun tedarik süreli ve duruş maliyeti yüksek parçalardır; arıza olmadan stokta tutulur.'),
  ('Toplantı başlangıcında \'güvenlik anı\' paylaşımı hangi amaca hizmet eder?', 'Güvenliği günlük bilinç düzeyinde tutmak ve deneyim paylaşmak', ['Toplantıyı uzatmak', 'Cezalandırmak', 'Yalnızca resmî bir zorunluluğu yerine getirip ardından konuyu kapatmak'], 'Kısa güvenlik paylaşımı, güvenliği sürekli gündemde tutar ve kazanılan dersleri herkesle paylaşır.'),
  ('Sürekli aşırı kuvvet, tekrar ve uygunsuz duruşun birlikte bulunması kas-iskelet riskini nasıl etkiler?', 'Etkiler birbirini güçlendirerek riski artırır', ['Risk azalır', 'Risk değişmez', 'Riskin yalnızca duruşa bağlı olup tekrar sayısından etkilenmemesi'], 'Kuvvet, tekrar ve duruş risk faktörleridir; bir arada bulundukları işler en yüksek risk grubundadır.'),
  ('Forkliftin yük taşırken devrilme riskini en çok artıran davranış hangisidir?', 'Yükü yukarıda tutarak virajı hızlı dönmek', ['Yükü yere yakın taşımak', 'Yavaş sürmek', 'Çatalları eğik ve tam geriye yatık konumda tutarak dönmek'], 'Yük yukarıdayken ağırlık merkezi yükselir ve ağırlık merkezi stabilite üçgeninin dışına çıkar; hızlı dönüş devrilmeye yol açar.'),
  ('Hendek (kazı) çalışmasında göçük riskine karşı hangi önlem alınır?', 'İksa, şev verme ya da sağlam desteklerle kazı yan yüzeylerini tutmak', ['Çalışanları hızlandırmak', 'Kazı kenarına yığın malzeme koymak', 'Hendek kenarına ağır iş makinesi park ederek zemini sıkıştırmak'], 'Kazı duvarları iksa veya uygun şevle desteklenmezse göçebilir; kazı kenarına yük konması riski artırır.'),
  ('Kaynak yapılan yerin yakınında yanıcı malzemeler varsa ne yapılmalıdır?', 'Malzemeleri uzaklaştırmak ya da yanmaz örtüyle korumak', ['Üzerini boyayıp yanıcılığını azaltmak', 'Hiçbir şey yapmamak', 'Malzemelerin üzerine su sıkıp yalnızca ıslak bırakmak'], 'Kıvılcımlar metrelerce uzağa sıçrayabilir; yanıcılar taşınmalı ya da alev geçirmez örtüyle kaplanmalıdır.'),
  ('Yanıcı sıvıları depolarken kullanılan \'yanmaz dolap\' ne sağlar?', 'Yangın anında içerideki sıvıların tutuşmasını geciktirir', ['Kimyasalları ısıtır', 'Kimyasalları karıştırır', 'Dolap içindeki kimyasalların kokusunu yok edip sızıntıyı gizler'], 'Yanmaz dolaplar çift cidarlı yapısıyla dış yangın ısısının içeriye geçmesini yavaşlatır.'),
  ('Yaşam döngüsü maliyeti (LCC) analizinde dikkate alınan unsur hangisidir?', 'Satın alma, işletme, bakım ve bertaraf maliyetlerinin toplamı', ['Yalnızca satın alma bedeli', 'Yalnızca işletme maliyeti', 'Yalnızca ürün tasarımı ve prototip üretim giderleri'], 'LCC, bir varlığın ömrü boyunca doğurduğu tüm maliyeti hesaba katar; ucuz alınan ürün işletimde pahalı olabilir.'),
  ('Teknoloji hazırlık seviyesi (TRL) ölçeği neyi gösterir?', 'Bir teknolojinin kavramdan kanıtlanmış sisteme olan olgunluk düzeyini', ['Teknolojinin fiyatını', 'Teknolojinin reklamını', 'Çalışanların bir teknolojiyi kullanım hızını ve eğitim süresini'], 'TRL 1\'den 9\'a artar; TRL 9, gerçek operasyonda kanıtlanmış sistemi ifade eder. Risk yönetiminde olgunluğu değerlendirmek için kullanılır.'),
  ('Bir fırının sıcaklığı her saat ölçülüyor ve kontrol sınırı dışında nokta çıkıyor. Operatörün ilk yapması gereken nedir?', 'Özel nedeni araştırmak, gerekirse üretimi durdurmak', ['Noktayı silmek', 'Sınırları genişletip noktayı normal saymak', 'Birkaç nokta daha çıkana kadar ölçümü bırakmak'], 'Sınır dışı bir nokta özel neden belirtisidir; neden bulunana ve giderilene kadar üretim riski değerlendirilir.'),
  ('Sürekli üretimde \'kendi kendine muayene\' (autonomous inspection) uygulamasının faydası nedir?', 'Hatayı üreten operatörün hatayı hemen görmesini ve düzeltmesini sağlar', ['Denetçileri artırır', 'Üretimi yavaşlatır', 'Muayene sonuçlarının yalnızca ay sonunda yönetime iletilmesini sağlar'], 'Operatör kendi işini hemen kontrol edince hata kaynağında yakalanır; geri bildirim gecikmesi azalır.'),
  ('Muayenede \'kritik, majör, minör\' kusur sınıflaması neye göre yapılır?', 'Kusurun kullanıcı güvenliği ve işlev üzerindeki etkisine göre', ['Kusurun rengine', 'Kusurun yerine', 'Kusurun tedarikçi tarafından bildirilme sıklığına'], 'Kritik kusur güvenliği tehlikeye atar, majör işlevi bozar, minör ise görünümü etkiler; kabul planı bunlar için ayrı AQL kullanır.'),
  ('Tabakalama (stratification) tekniği veri analizinde ne işe yarar?', 'Veriyi kaynağa (makine, vardiya) göre gruplayıp gizli farkları görmeyi sağlar', ['Verileri silmeyi', 'Verileri toplamayı', 'Verilerin tamamını tek ortalamayla özetleyip varyasyonu gizlemeyi'], 'Tabakalama, karışık verinin altındaki kaynak farklarını ortaya çıkarır ve hedefe yönelik iyileştirmeye yardım eder.'),
  ('Süreç yeteneği çalışmasında verinin normal dağılımdan sapması neden önemlidir?', 'Cp/Cpk yorumu normal dağılım varsayımına dayanır', ['Önemi yoktur', 'Veri artar', 'Normal olmayan veri için ölçüm aletinin kalibrasyonu zorunlu olarak gereksiz kalır'], 'Yeterlilik indeksleri normal dağılım varsayar; çarpık dağılımlarda uygun dönüşüm ya da yöntem gerekir.'),
  ('Arıza modu ile arıza mekanizması arasındaki fark nedir?', 'Mod gözlenen arıza biçimi, mekanizma onun fiziksel/kimyasal nedenidir', ['İkisi aynıdır', 'Mekanizma arızanın maliyetidir', 'Mod, arızanın zamanını yalnızca saat olarak ifade eder ve neden içermez'], 'Örneğin \'kırılma\' bir moddur; \'yorulma çatlağı ilerlemesi\' mekanizmadır. Kök neden analizinde mekanizmaya inilir.'),
  ('\'Tasarım marjı\' (design margin) güvenilirlik açısından ne sağlar?', 'Beklenen yük ile dayanım arasındaki farkı büyüterek arıza olasılığını azaltır', ['Maliyeti azaltır', 'Daha hafif ürün sağlar', 'Tasarım değişikliklerinin kayıtlarını otomatik güncel tutar'], 'Yük-dayanım örtüşmesi azaldıkça arıza olasılığı düşer; marj, belirsizliklere karşı tampondur.'),
  ('FMEA\'da \'önerilen önlem\' kolonu hangi hata modlarına öncelikle yazılır?', 'Yüksek şiddetli ve yüksek riskli (yüksek RPN ya da AP) olanlara', ['Hata modu bulunmayan satırlara', 'Yalnızca en küçük risklere', 'Yalnızca daha önce hiç görülmemiş yeni hata modlarına'], 'Kaynaklar sınırlıdır; önce şiddeti ve riski en yüksek hata modlarına önlem atanır.'),
  ('Projeye başlanırken yapılan \'ön mortem\' (pre-mortem) çalışmasının mantığı nedir?', 'Projenin başarısız olduğunu varsayıp nedenlerini önceden sıralamak', ['Proje bittikten sonra rapor yazmak', 'Sorumlu aramak', 'Başarılı bir projenin neden başarılı olduğunu varsayıp başarı nedenlerini ödüllendirmek'], 'Pre-mortem, gelecekte çökmüş bir proje hayal ederek ekibin gizli kaygılarını ve riskleri başta ortaya çıkarmasını sağlar.'),
];
